	[3110] = {
		Title = "丢失的宝石-寻找宝石的行踪",
		Description = { "帮我找到失踪的钻石。艾尔贝塔的乔尼塔、斐扬的金恩方、盖佩的雷布罗，这三位王国最大的宝石商人，或许会知道钻石的下落。" },
		Summary = ""
	},
	[3111] = {
		Title = "丢失的宝石-雷布罗的提议",
		Description = { "我有一个建议，如果你想获得想要的情报，就帮我做一件事。只要你帮我把药交给斐扬的名叫乌尔雅的议员，我就把情报告诉你。" },
		Summary = ""
	},
	[3112] = {
		Title = "丢失的宝石-斐扬的议员香雅",
		Description = { "你是来求我的，就帮我做一件事吧。请你帮我搜集修理损坏的汤药机的材料。" },
