	[4999] = {
		Title = "Extermination Crisis",
		Description = {
			"Our great frog race is now endangered because many travellers come here and take our eggs as a kind of souvenir. I even heard there are many left on the ground here and there, so I need your help. Please bring back ^FF0000100 Spawn^000000."
		},
		Summary = "Bring 100 Spawn to King Froggie VII"
	},
	[5000] = {
		Title = "灭族危机",
		Description = { "由于最近来此拜访的旅人会抢走我们的蛋当作是纪念品，导致青蛙陷入灭族危机中。而且还有人会故意将那些蛋四处乱扔，所以麻烦你替我们找回青蛙蛋100颗就好。" },
		Summary = "将青蛙蛋交给青蛙7世吧！"
	},
	[5001] = {
		Title = "同族的复仇",
		Description = { "对蛇而言我们青蛙是种健康食品，不觉得我们真的很可怜吗？请你替我们进行同族的复仇，只要消灭黑蛇50只应该就能消青蛙同伴们的心头之恨。" },
		Summary = "消灭50只黑蛇"
	},
	[5002] = {
		Title = "青蛙的英雄",
		Description = { "你的英勇行为可以成为青蛙们的借鉴，因此想将你的楷模写进青蛙史记中，但需要足以证明你英勇行为的证物，所以请你带回毒牙100颗。" },
		Summary = "将毒牙交给青蛙7世吧！"
	},
	[5003] = {
		Title = "青蛙隐身术",
		Description = { "终于想到可以拯救同族的方法了！答案就在青蛙史记中，听说伟大的青蛙3世先前制造出可以躲避蛇的耳目，关于青蛙隐身术的秘药，你快去带回鳞片皮肤50个。" },
