	[7052] = {
		Title = "死亡之塔-塔的封印！",
		Description = { "找到了第四把钥匙！好像是使用强制的力量，将通往魔界的通道和其他地方连接了起来。不知道塔内出现的天使们与此有没有关系。" },
		Summary = "再次探索塔内的封印"
	},
	[7053] = {
		Title = "死亡之塔-他们想要的东西……",
		Description = { "找到第五把钥匙的时候，发现了巴尔蒙德的手册。也许这就是布雷德所说的“雷肯贝尔正在寻找的东西”。回去告诉布雷德。" },
