	},
	[7056] = {
		Title = "信使-阿克的委托",
		IconName = "ico_ep.bmp",
		Description = { "在拉皮内的驻地“辉煌领域”见到了拉皮内“阿克”，他让我帮他去寻找朋友“泰拉”，说泰拉有用杂草打结，标记走过的路线的习惯。" },
		Summary = "寻找泰拉的痕迹。"
	},
	[7057] = {
		Title = "信使-阿克的委托",
		IconName = "ico_ep.bmp",
		Description = { "在辉煌领域驻地附近找到了泰拉留下的标记。痕迹好像指向“南方”。继续寻找吧。" },
		Summary = "寻找泰拉的痕迹。"
