	[7219] = {
		Title = "高阶训练第2阶段克雷斯特汉姆古城",
		Description = { "乐园团高阶训练的第2阶段由克雷斯特汉姆古城展开，玩家在修道院前见到佑翰并接受训练课程。" },
		Summary = "与佑翰见面"
	},
	[7220] = {
		Title = "第2阶段之1-死神",
		Description = { "佑翰交给玩家的课题为击败出现在修道院1楼的强悍冤魂恶灵。" },
		Summary = "消灭恶灵20只"
	},
	[7221] = {
		Title = "第2阶段之2-堕落的圣职者",
		Description = { "牧师们原本在修道院里修道，不过堕落的圣职者无法再继续救赎人类，需令他们无法再次苏醒过来……" },
		Summary = "消灭?神官10只"
	},
	[7222] = {
		Title = "向晤勒报告",
		Description = { "虽然还有点疑点，不过佑翰却说训练课题已经全部结束，回去乐园团向晤勒报告吧！" },
		Summary = "向晤勒报告"
	},
	[7223] = {
		Title = "高阶训练第3阶段艾音布罗克",
		Description = { "乐园团派来的成员'崎蓝'应该正在艾音布罗克的南边等待交付下一个训练课题，虽然晤勒声称当作是休息要玩家轻松地前往……" },
		Summary = "和崎蓝对话"
	},
	[7224] = {
		Title = "第3阶段之1-三叶铁甲虫",
		Description = { "崎蓝是属于慢郎中的个性，因此悠闲地在附近的原野散完步后，便提出击败三叶铁甲虫的课题，而这似乎是来自附近居民的委托。" },
		Summary = "消灭三叶铁甲虫30只"
	},
	[7225] = {
		Title = "第3阶段之2-这是恶梦(1)",
		Description = { "这是100%反应出艾音布罗克民怨的训练课题，只需消灭使都市北边产生乌烟的元凶即可。" },
		Summary = "消灭废气魔30只"
	},
	[7226] = {
		Title = "第3阶段之2-这是恶梦(2)",
		Description = { "这是100%反应出艾音布罗克民怨的训练课题，只需消灭使都市北边产生乌烟的元凶即可。" },
		Summary = "消灭毒液魔30只"
	},
	[7227] = {
		Title = "第3阶段之2-这是恶梦(3)",
		Description = { "艾音布罗克的民怨中最严重的问题之一，便是被生产为兵器却遭到遗弃的熊玩偶，崎蓝说熊玩偶是个强敌要玩家小心。" },
		Summary = "消灭玩偶熊5只"
	},
	[7228] = {
		Title = "向晤勒报告",
		Description = { "艾音布罗克居民的委托兼训练已全数完成，回到乐园团向晤勒报告吧！" },
		Summary = "向晤勒报告"
	},
	[7229] = {
		Title = "高阶训练第4阶段冰洞穴",
		Description = { "最终阶段的训练场所为位于拉赫的东北边、伊达平原尽头的冰洞穴。有个纳俄米的成员应该正在洞穴入口等着。" },
		Summary = "和纳俄米对话"
	},
	[7230] = {
		Title = "第4阶段之1-小雪兽",
		Description = { "100%反应出附近居民民怨的训练课题果然正在等着，去击败对采集冰块造成妨碍的小雪兽吧！" },
		Summary = "消灭小雪兽30只"
	},
	[7231] = {
		Title = "第4阶段之2-冰块！",
		Description = { "决定额外击败繁殖速度相当快速的小雪兽，并且接受纳俄米的私人请托。虽然纳俄米强烈否认，但这绝对是剉冰的材料。冰块一角30个、甜调味料1个、牛奶1个。" },
		Summary = "消灭小雪兽30只并带回剉冰材料"
	},
	[7232] = {
		Title = "向晤勒报告",
		Description = { "先不管剉冰，总之已经适当地消灭掉对采集冰块造成妨碍的小雪兽。无论是委托还是训练已全数完成，回到乐园团向晤勒报告吧！" },
		Summary = ""
	},
	[7233] = {
		Title = "第4阶段的高级玩家前往异界",
		Description = { "晤勒交付给玩家的最后训练课题，便是去见派至灰暗的尘世远征队的乐园团成员玛格蕾，并协助他。" },
		Summary = "与玛格蕾见面"
	},
	[7234] = {
		Title = "玛格蕾的请托",
		Description = {
			"在远征队营区遇到的玛格蕾正为尚未归队的同伴米鲁和米内担心，玛格蕾要玩家去找米鲁和米内，并打听看看他们究竟发生何事。米鲁在东边，米内则是在西边，先去找米鲁再去找米内吧！"
		},
		Summary = "与米鲁和米内见面"
	},
	[7235] = {
		Title = "4第4阶段米鲁的情况",
		Description = { "双胞胎兄弟米鲁和米内因为一点小事而发生口角，于是便各自往反方向的方向去查探。米鲁夸下海口说要抓到猪笼草，于是便请玩家帮忙。" },
		Summary = "消灭猪笼草1只"
	},
	[7236] = {
		Title = "第4阶段米内的情况",
		Description = { "因为和米鲁的摩擦导致米内必须独自面对捕虫堇妖，帮助米内取得捕虫堇妖的攻略方法吧！" },
		Summary = "消灭捕虫堇妖5只"
	},
	[7237] = {
		Title = "向晤勒报告",
		Description = { "玛格蕾表示，玩家解决自己的困扰便等于是完成训练，因此要玩家回到乐园团向晤勒报告。" },
		Summary = "向晤勒报告"
	},
	[7238] = {
		Title = "涂仑的差事(容易)",
		Description = { "这是乐园团铁匠涂仑的委托，差事的重点为带回涂仑需要的矿物'铁矿石20个、铁10个'。" },
		Summary = "收集铁矿石20个、铁10个"
	},
	[7239] = {
		Title = "涂仑的差事(普通)",
		Description = { "这是乐园团铁匠涂仑的委托，差事的重点为带回涂仑需要的老旧的铁板20个，当然，如果能顺便消灭矿工魔的话，更是锦上添花！" },
		Summary = "收集老旧的铁板20个"
	},
	[7240] = {
		Title = "涂仑的装备强化1次性券",
		Description = { "帮忙解决涂仑委托后保证可拿到谢礼的装备强化券，可从乐园团斗篷？、乐园团制服？、乐园团短靴？中择一强化。强化的结果每次都将随机变化，因此必须谨慎思考。" },
		Summary = ""
	},
	[7241] = {
		Title = "涂仑的差事–明天继续",
		Description = { "涂仑现在所需的物品似乎已经足够，过一天后再去找他吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[7242] = {
		Title = "陪小猫咪玩耍",
		Description = {
			"这是在绵绵岛遇见的资深船员拉脱的委托，他因为担心还年幼的小猫咪，因此请玩家去找小猫咪一起玩耍。去找拉脱说的小猫咪吧！分别是白毛的罗熙、黑毛的罗库和黄毛的查洛。"
		},
		Summary = ""
	},
	[7243] = {
		Title = "猫咪探险-喵喵指南针",
		Description = { "从从自称为喵喵冒险队的小猫咪们收到冒险卡A，似乎为启动喵喵队所制作的各种机关所必须的，将卡片插入起步指南针后游戏便正式开始。" },
		Summary = ""
	},
	[7244] = {
		Title = "猫咪探险-喵喵指南针",
		Description = { "喵喵赛跑开始了，必须在规定时间内依序通过指南针。顺序为[红焰]-[苍天]-[金沙]-[新绿]-[白云]。" },
