		Description = { "喵喵赛跑开始了，必须在规定时间内依序通过指南针。顺序为[红焰]-[苍天]-[金沙]-[新绿]-[白云]。" },
		Summary = ""
	},
	[7246] = {
		Title = "猫咪探险-现在去见面",
		Description = { "查洛说位于绵绵岛中央的蝴蝶号附近有位名侦探，去见见伟大的名侦探和他的朋友吧！" },
		Summary = ""
	},
	[7247] = {
		Title = "猫咪探险-让喵喵机停下来！",
		Description = { "虽然不知道他是否真的是侦探，但自称是侦探亨喵和他的朋友喵森说，若是放在面前的机器爆炸的话，整个岛都会被炸飞，因此希望玩家制止机器爆炸。" },
		Summary = ""
	},
	[7248] = {
		Title = "猫咪探险-让喵喵机停下来",
		Description = { "" },
		Summary = ""
	},
	[7249] = {
		Title = "猫咪探险-喵喵机！明天同一时间",
		Description = { "根据亨喵和喵森的说法，这个叫作喵喵机的机器每次都会爆炸，但不知道何时会再次爆炸，因此决定明天再去找找看。" },
		Summary = "",
