	[7250] = {
		Title = "猫咪探险-宝藏？",
		Description = { "把喵喵机停下来后亨喵和喵森说有好康情报，没头没尾地说什么宝藏，亨喵说宝藏就藏在蝴蝶号里面，虽然不知道是不是骗人的，但还是去找找看吧！" },
