	[7264] = {
		Title = "告诉主厨猫乐司",
		IconName = "ico_nq.bmp",
		Description = { "虽然猫可莉很认真打扫，但手碰不到的地方放有猫饼干，而那个猫饼干就是一切事情的罪魁祸首，必须将这件事告诉主厨猫乐司，以洗清猫可莉的冤屈。" },
		Summary = "和猫乐司对话，以洗清猫可莉的冤屈。"
	},
	[7265] = {
		Title = "主厨猫乐司的愤怒",
		IconName = "ico_nq.bmp",
		Description = { "将猫饼干和虫虫的事告诉主厨后，主厨非常生气，还是先等他冷静下来后再跟他说话会比较好！" },
		Summary = "和猫乐司对话"
	},
	[7266] = {
		Title = "主厨猫乐司的命令",
		Description = { "主厨猫乐司宣布往后一天中有一餐要提供猫饼干，并要求带回制作猫饼干的材料，谷物10个和纯调味料1瓶。" },
		Summary = "将猫乐司的命令谷物10个、纯调味料1瓶告知猫可莉。"
	},
	[7267] = {
		Title = "和猫可莉的约定时间",
