	},
	[7570] = {
		Title = "消灭魔族！",
		Description = { "收到来自副队长 哈因的委托，要求消灭从魔神之塔最上层而下的魔族。" },
		Summary = "消灭魔神影子"
	},
	[7571] = {
		Title = "资料(1)魔神梦罗克远征队",
		Description = {
			"名为达纳托斯塔的塔，是数千年前神魔大战时模族所设置魔界大门，之后的数百年间皆是荒废的状态，直至魔神梦罗克为降至现今世界才又再次启用，而且为消灭魔神世世代代不断抗争。"
		},
		Summary = ""
	},
	[7572] = {
		Title = "露诗……？",
		Description = { "在勘察魔神之塔途中遇见的谜样刺客少女 露诗。露诗为修复身体而请求协助……在他的身体恢复正常前就努力撑住吧！" },
		Summary = "协助露诗修复身体"
	},
	[7573] = {
		Title = "魔剑士 达纳托斯",
		Description = { "为使魔剑士 达纳托斯成功封印魔神梦罗克，需阻止魔神力量碎片前来。" },
		Summary = "消灭魔神力量碎片"
	},
	[7574] = {
		Title = "资料(2)达纳托斯塔的真面目",
		Description = { "不过是座魔界大门的塔，会为何被称为达纳托斯塔呢？这是因为魔剑士 达纳托斯成功阻止魔神梦罗克的降临，并且成功将其封印，故以达纳托斯之名命名该塔。" },
		Summary = ""
	},
