	[8076] = {
		Title = "克黎泽与卡拉",
		Description = { "卡拉……虽想去见她……没，没事，不该对初次见面的你说这些事给你负担，就当作是在艾音贝赫有个痴情人克黎泽吧，忘掉也没关系啦……" },
		Summary = ""
	},
	[8077] = {
		Title = "克黎泽与卡拉",
		Description = { "请把这个交给他好吗？这是我爱惜的乐器，希望他看到乐器后能得到安慰" },
		Summary = "把卡拉的小提琴转交给克黎泽"
	},
	[8078] = {
		Title = "克黎泽与卡拉",
		Description = { "这家伙！端看那纹路肯定是我买给女儿的小提琴！你是小偷吧！你最好马上把它交出来！" },
		Summary = "把卡拉的小提琴抢走"
	},
	[8079] = {
		Title = "克黎泽与卡拉",
		Description = { "请你帮我买一朵花给她好吗？　我既没钱去找她又不一定见得到……拜？你了" },
		Summary = "送一朵花给卡拉"
	},
	[8080] = {
		Title = "克黎泽与卡拉",
		Description = { "万一你还有机会回到艾音贝赫的话，请你告诉克黎泽我非常感谢他……还有……还有……非常想念他……时时刻刻都在思念着他……请你……一定……一定要转告他……呜" },
		Summary = "向克黎泽转达喀尔拉的话"
	},
	[8081] = {
		Title = "克黎泽与卡拉",
		Description = { "你回去时请顺便见一下我母亲吧，我母亲应该也有话要说" },
		Summary = "去见克黎泽的母亲"
	},
	[8082] = {
		Title = "克黎泽与卡拉",
		Description = { "这该如何是好啊，旅行者？我不希望两个村落的一对情侣就这样一直被拆散" },
		Summary = ""
	},
	[8083] = {
		Title = "克黎泽与卡拉",
		Description = { "虽然不能提升到像我们一样的等级，但端看你能贡献多少的煤矿，来决定你能提升多少的等级呵~呵呵呵呵！" },
		Summary = "要煤矿拿给莎特娜"
	},
	[8084] = {
		Title = "克黎泽与卡拉",
		Description = { "这些煤矿我会用在振兴我们家族上，你再多拿给我一点会更好啦！" },
		Summary = "要煤矿拿给莎特娜"
	},
	[8085] = {
		Title = "克黎泽与卡拉",
		Description = { "若你到艾音贝赫见到克黎泽青年的话，转告他过来一趟这边的家，届时叫他穿着要体面一点，算了还是不要强人所难了！" },
		Summary = "向克黎泽转达讯息"
	},
	[8086] = {
		Title = "克黎泽与卡拉",
		Description = { "啊啊？你说什么？！你替我打理了佩达仁家族是吗？另外拉的母亲叫我穿的体面一点去拜访她吗？！" },
		Summary = ""
	},
	[8087] = {
		Title = "克黎泽与卡拉",
		Description = { "不过只是？了衣服你就感到忐忑不安，果然没出息……男生还是要穿西装，不知我儿子适不适合，反正像结婚礼服最适合了" },
		Summary = "拿给克黎泽适合的衣服"
	},
	[8088] = {
		Title = "克黎泽与卡拉",
		Description = { "非常感谢你，不仅帮了我，还给我反省的机会……我一定会把与卡拉的爱情付诸实现的" },
		Summary = ""
	},
	[8089] = {
		Title = "被窃走的宝石",
		Description = { "疑犯应该是打从宝石不见起就消失踪影，曾在那府上当过仆人的波毕所偷走的，关于逃跑的仆人情报你可以向这府上的其他仆人打听即可，那就麻烦你了" },
		Summary = "取得波毕的情报"
	},
	[8090] = {
		Title = "被窃走的宝石",
		Description = { "其实我来这里也没多久，对那小孩也不是很了解，你去问府内工作的曼森吧" },
		Summary = "去找曼森"
	},
	[8091] = {
		Title = "被窃走的宝石",
		Description = { "那孩子是在庭院里工作的园艺师杰妮所领养的小孩，详细的你去问杰妮吧，她可能会知道更多的事情" },
		Summary = "去找杰妮"
	},
	[8092] = {
		Title = "被窃走的宝石",
		Description = { "那么首先去3天前在波毕失踪前曼森差使他去的那个市场吧" },
		Summary = "去市场"
	},
	[8093] = {
		Title = "被窃走的宝石",
		Description = { "昨晚有人交代我说若有人像你这样询问的话，就叫你到冰洞穴来，名字好像是……罗甘？罗根？长相倒是蛮恐怖" },
		Summary = "去冰洞穴"
	},
	[8094] = {
		Title = "被窃走的宝石",
		Description = { "叫你来找的应该是文森特吧……不知又牵扯到何事……我只是依他的指示办事而已，所以别再伤害我了~" },
		Summary = "去找文森特"
	},
	[8095] = {
		Title = "被窃走的宝石",
		Description = { "我既然受人之？必须完成任务才能拿到钱的关系，在大神官来之前我会想办法找回波毕" },
		Summary = "去找波毕"
	},
	[8096] = {
		Title = "被窃走的宝石",
		Description = { "我会回去但不是现在，请转告他们我平安无恙，而且我很快就回去了" },
		Summary = "去找文森特"
	},
	[8097] = {
		Title = "被窃走的宝石",
		Description = { "呼呜……没事就放心了……我要马上去告诉杰妮，她一直很担心着" },
		Summary = "向杰妮转达波毕的消息"
	},
	[8098] = {
		Title = "被窃走的宝石",
		Description = { "非常谢谢你，希望你好心有好报，旅途愉快" },
		Summary = "去找文森特"
	},
	[8099] = {
		Title = "被窃走的宝石",
		Description = { "一起给你的东西是要交给杰德的你的推荐书，请你交给杰德吧" },
		Summary = "去找杰德"
	},
	[8100] = {
		Title = "大神官的推荐书",
		Description = { "推荐书我会帮你写，不过要麻烦你去找冰心脏40个后，再到神殿内部的教皇办公事吧" },
		Summary = "带着冰心脏40个去教皇办公事见教皇"
	},
	[8101] = {
		Title = "大神官的推荐书",
		Description = { "谢谢你讲……有趣的……故事……我要去……礼拜了……再见……" },
		Summary = "去找杰德大神官"
	},
	[8102] = {
		Title = "大神官的推荐书",
		Description = { "抱歉请你离开一下好吗？我们要聊一下事情请你到隔壁房间稍候，别忘了我的叮？……" },
		Summary = ""
	},
	[8103] = {
		Title = "大神官的推荐书",
		Description = { "劝你别跟杰德大神官走的太近，如果你不想遭到不测的话" },
		Summary = "去找杰德大神官"
	},
	[8104] = {
		Title = "大神官的推荐书",
		Description = { "啊……我是苦口婆心的告诉你，位于神殿内的圣域千万别靠进它！" },
		Summary = ""
	},
	[8105] = {
		Title = "大神官的推荐书",
		Description = { "我上次曾劝你说会被杰德害到，结果却是相反，多亏你杰德的立场变得更艰难，来这里的外人通常无法全身而退，不过念在与杰德的情分上只有这次让你回去吧" },
		Summary = "去找杰德大神官"
	},
	[8106] = {
		Title = "布鲁斯彼特的行踪",
		Description = { "我女儿最近好像在谈恋爱，她说要去别的村落后就没消息了，唉……把女儿养大了却这样，一定是跟交往的对象去旅行了" },
		Summary = "去见好友罗雪莲"
	},
	[8107] = {
		Title = "罗雪莲的证词",
		Description = { "好羡慕布鲁的情人，不久前开始交往，名字叫……哦……好像是外国名字，总之祝福他们？，其实以布鲁的条件不需要男生吧！" },
		Summary = "去找村落内的外国人"
	},
	[8108] = {
		Title = "外国人卡汀休尔",
		Description = { "你说……情人吗，那已经是过去式了，现在完全与我无关了，我不想跟任何人有牵扯" },
		Summary = "去找孙达鲁"
	},
	[8109] = {
		Title = "布鲁斯彼特的香味",
		Description = { "我女儿……没错，不需特别打扮就会有芬芳的香味，她母亲也散发着类似的香味哩……" },
		Summary = "在里希塔乐镇寻找布鲁斯彼特的香味"
	},
	[8110] = {
		Title = "布鲁斯彼特的香味",
		Description = { "确定有闻到一股香味，应该是有香味的人刚留下的，总觉得这香味不是本村所散发的样子" },
		Summary = "回到拉赫去见罗雪莲"
	},
	[8111] = {
		Title = "罗雪莲的证词",
		Description = { "好像是说要查什么东西，跑去别的村落了，从那之后就没消息，若去在本村他以前常去的地方，或许能找到线索吧" },
		Summary = "去找菲依雅泉井"
	},
	[8112] = {
		Title = "菲依雅的泉井",
		Description = { "那里比较湿滑的缘故，只要一不小心就会掉落泉井中……这泉井还满深的要特别小心，呼呼……" },
		Summary = "去找孙达鲁"
	},
	[8113] = {
		Title = "布鲁斯彼特的日记",
		Description = { "虽然日记本在衣柜上面，但我不会打开的，担心归担心，我相信他会平安回来的" },
		Summary = "去找衣柜上面"
	},
	[8114] = {
		Title = "布鲁斯彼特的日记",
		Description = { "虽然日记本在衣柜上面，但我不会打开的，担心归担心，我相信他会平安回来的" },
		Summary = "去找衣柜上面"
	},
	[8115] = {
		Title = "布鲁斯彼特的日记",
		Description = { "虽找到日记本了……但这算是属于私领域吧？我看还是别动好了" },
		Summary = "去见卡汀休尔"
	},
	[8116] = {
		Title = "可疑的卡汀休尔",
		Description = { "疑惑解除了吗？身？冒险家最好是到处去游山玩水，不需要追根究底" },
		Summary = "去见罗雪莲"
	},
	[8117] = {
		Title = "罗雪莲的证词",
		Description = { "啊啊……你是说下方的湖水吗？　因风景好气氛佳，所以颇受欢迎，难怪住在那上面的卡汀休尔也常去的样子" },
		Summary = "去找菲依雅泉井"
	},
	[8118] = {
		Title = "菲依雅的泉井",
		Description = { "我看到一位常来这里的男生……每次都在那危险的边边处盯着泉井看，我看那样子，嗯……想必心事重重吧" },
		Summary = "去找孙达鲁"
	},
	[8119] = {
		Title = "孙达鲁对话",
		Description = { "睁眼说瞎话吧？……女儿的失踪……想隐瞒的时候……就会说谎？……呃呃……" },
		Summary = "带着布鲁斯彼特的日记本去找卡汀休尔"
	},
	[8120] = {
		Title = "与卡汀休尔的对话",
		Description = { "你现在满意了吧？把不利自己的证据都烟灭了！杀害布鲁斯彼特的疑犯就是卡汀休尔！" },
		Summary = "与卡汀休尔继续对话"
	},
	[8121] = {
		Title = "与卡汀休尔对话",
		Description = { "他的心防快要破解了，若拿给他看能引起他以前干的事情回忆的话，也许就能招供了……唉" },
		Summary = ""
	},
	[8122] = {
		Title = "与卡汀休尔对话",
		Description = { "……布鲁斯彼特的日记本上写着不小心被自己的脚绊倒后，竟被自己杀人的工具铁管刺中身体……莫非是他们从地狱里……带我回去……也说不定……" },
		Summary = "回到菲依雅泉井"
	},
	[8123] = {
		Title = "阿育塔雅的名？，羊肉火锅",
		Description = {
			"啊……虽然很多人都会做羊肉火锅，但我想向你特别推荐^3131FF玛丽？德？斯派制作的羊肉火锅。她制作的羊肉火锅可以说是幻想中才有的佳肴。我会去让她？你准备一份的。"
		},
		Summary = ""
	},
	[8124] = {
		Title = "阿育塔雅的名？，羊肉火锅",
		Description = { "我知道有个卖非常新鲜的虾的人。他的名字是“^3131FF胖保尔”。你去跟他说要买制作羊肉火锅的1公斤20个虾。明白了吗？" },
		Summary = "把20个虾交给玛丽？德？斯派"
	},
	[8125] = {
		Title = "阿育塔雅的名？，羊肉火锅",
		Description = { "不久之前，我在村子周围走的时候，发现了一棵长了很多柠檬的树。但是那家的主人不做生意，也许不会把柠檬卖给你。如果可以的话，请你去那里帮我买些柠檬。" },
		Summary = "把柠檬交给玛丽？德？斯派"
	},
	[8126] = {
		Title = "阿育塔雅的名？，羊肉火锅",
		Description = { "好了，接下去请你去市场购买“^CE0000辣椒酱”和其他的材料。只要和市场的商人一说，他就知道你要买什么东西了。" },
		Summary = "把辣椒酱和其他材料交给玛丽？德？斯派"
	},
	[8127] = {
		Title = "莫莫塔罗体验官",
		Description = {
			"嗯，据村长说，最近鬼怪通过黑客技术，从人们的账户里偷到了20亿的钱……不过你也知道，我们村民每天在这儿说话，不去升级，所以没有能力对付鬼怪……得请你帮帮我们。"
		},
		Summary = "扫荡鬼怪"
	},
	[8128] = {
		Title = "莫莫塔罗体验官",
		Description = { "好了，莫莫塔罗的事情就到这儿了。你去和一开始见到的女职员说话，就可以领取我们？你准备的商品。" },
		Summary = ""
	},
	[8129] = {
		Title = "莫莫塔罗体验官",
		Description = { "……本来我应该让你回去的，不过我想看看你真正的实力……怎样……？我再给你一次机会。这次即使失败，^3163FF也无法重新挑战，而且对你来说将会非常困难。" },
		Summary = "扫荡鬼怪"
	},
	[8130] = {
		Title = "莫莫塔罗体验官",
		Description = { "呵呵呵……真了不起。现在我知道了你的实力。见到你这样的人才，真是我的荣幸。时间到了，我把你送到出口。很高兴认识你。别忘了拿礼物～" },
		Summary = ""
	},
	[8131] = {
		Title = "天津城城主的母亲",
		Description = { "这是城主的母亲疗养的场所。她连着几个月身体都不太好，所以一直住在这里。" },
		Summary = ""
	},
	[8132] = {
		Title = "天津城城主的母亲",
		Description = { "你是外地来的人，说不定可以治好我母亲的病。拜托你了。母亲住在城外的住宅里。治疗成功之后，请你再来找我。" },
		Summary = "寻找？城主母亲治病的方法"
	},
	[8133] = {
		Title = "狐狸的歌声",
		Description = { "大师，大师，狐狸跟来了。大声喊把它吓走。声音太小的话，它不会逃走。都跟着来到北部的神社了。啦啦啦，啦啦啦，啦啦啦啦啦啦～啦啦啦，啦啦啦，啦啦啦啦啦啦～" },
		Summary = ""
	},
	[8134] = {
		Title = "北部神社的少年",
		Description = { "听说只要表现出比狐狸更强的气势，它就会被人吓走。请你用力大喊一声。" },
		Summary = ""
	},
	[8135] = {
		Title = "击退狐狸",
		Description = { "^FF6060呜呜！呜呜！呜呜！该死的人类！竟然把我赶走！我诅咒你们！我恨你们！！我诅咒把我变成这样的石田家族！诅咒！人类，等着瞧！" },
		Summary = "带着狐狸的尾巴，回到城主那里"
	},
	[8136] = {
		Title = "危险的森林",
		Description = { "听说有很多冒险家在前面的这片森林里失踪了。我？哈哈，别？我担心。我熟悉这边的地理，而且也不怕怪物之类的东西。哈哈哈。" },
		Summary = ""
	},
	[8137] = {
		Title = "三岔路的碑石",
		Description = { "向右走自己会消失，向左走会变哑，向前走永远走不到终点" },
		Summary = ""
	},
	[8138] = {
		Title = "灰狼的警告",
		Description = { "……这个森林很危险。他不希望人类进入这个森林。他的名字是不死之神科雪伊……应该在它发觉之前，尽快离开这个森林。" },
		Summary = ""
	},
	[8139] = {
		Title = "灰狼的委托",
		Description = { "希望你这样有勇气的人类帮帮我。你愿意帮我吗？在这里说话不太方便。你坐到我背上来。请你跟我去一个地方。" },
		Summary = ""
	},
	[8140] = {
		Title = "玛丽亚？莫雷布纳",
		Description = {
			"首先必须把她从那里救出来。听说有一把可以打开所有锁的“^0000ff金色钥匙”。听说村里有人会制作那种钥匙。你去找到可以制作“^0000ff金色钥匙”的人，然后和他说一说。"
		},
		Summary = "在莫斯科寻找可以制作金色钥匙的人"
	},
	[8141] = {
		Title = "莫斯科的铁匠",
		Description = { "我就是知道怎制作金色钥匙的人！可以打开所有东西的钥匙，听上去是不是很方便？但其实并不是这样。因？需要很多难找的材料。你先去搜集^0000ff25个钢铁。" },
		Summary = "把25个钢铁交给莫斯科的铁匠"
	},
	[8142] = {
		Title = "金色的钥匙",
		Description = { "制作金色钥匙所需的材料是，^0000ff2个诅咒的红宝石、3个黄金、1个红色戒指、2个卢萨卡的头发、10团金线……听明白了的话，就快去搜集。我在这儿等你。" },
		Summary = "搜集2个诅咒的红宝石、3个黄金、1个红色戒指、2个卢萨卡的头发、10团金线，交给莫斯科的铁匠"
	},
	[8143] = {
		Title = "巴希丽的红色戒指",
		Description = {
			"红色戒指我在很久以前就送给了我的小女儿玛雪佳。但是玛雪佳……已经死了……现在只剩下大女儿榴芭芭了。虽然榴芭芭也是我心爱的女儿，但失去孩子的空虚感却是无法弥补的……"
		},
		Summary = ""
	},
	[8144] = {
		Title = "玛雪佳的行踪",
		Description = {
			"啊，那个红色戒指……没错。父亲把它送给了玛雪佳。但是妹妹在第二天去森林里的沼泽附近散步的时候失踪了。人们四处寻找，但没有找到。人没有找到，戒指也没有找到。我想她也许是带着戒指逃跑了。"
		},
		Summary = ""
	},
	[8145] = {
		Title = "玛雪佳的行踪",
		Description = {
			"嗯？我好像听到过这些，不过我也不太清楚……你到沼泽附近去一趟不就知道了吗？啊！对了，你去沼泽附近的时候，能帮我从那里的“尖尖树”上搜集^0000ff50个尖刺吗？"
		},
		Summary = "把50个尖刺交给牧羊女"
	},
	[8146] = {
		Title = "木笛的歌声",
		Description = { "这，这是什么啊？！笛子里怎会发出这种声音！？还是第一次这样！真让人难受！这个笛子，我送给你了！" },
		Summary = ""
	},
	[8147] = {
		Title = "木笛的歌声",
		Description = { "我不愿意……用这个笛子……和红色戒指交换！你总得告诉我事实吧！我会告诉你父亲！告诉他，然后让你付出代价！" },
		Summary = "向巴希丽报告"
	},
	[8148] = {
		Title = "伤心的大妈",
		Description = { "你去过莫斯科的沼泽吗？你在那里看到我女儿了吗？不管怎样，只要能知道她的下落就行了。呜呜呜。" },
		Summary = ""
	},
	[8149] = {
		Title = "伤心的大妈",
		Description = { "你去见卢萨卡的时候，一定要带着“^0000ff带有神的祝福的神圣的水”，在晚上11点到清晨5点之间过去。请你一定要帮我打听到女儿的下落。拜托你了。" },
		Summary = "寻找女儿的下落"
	},
	[8150] = {
		Title = "卢萨卡的恋人",
		Description = {
			"他离开的那个晚上，说要去卢恩·米德加兹的首都。不知道现在还在不在那里……那个人的名字是“^0000ff伊格尔”。啊！请你帮我把这个交给他。这是他送给我的非常贵重的耳环。"
		},
		Summary = "寻找伊格尔"
	},
	[8151] = {
		Title = "异国的流浪者",
		Description = {
			"那是我离开莫斯科，到这里来旅行的时候一起来的人。我们是一起来到了这里，但不久前就分开了。他说忘不了心爱的人，看上去很彷徨。嗯……他说要去哪里来着……？他好像说过想去沙漠旅行。"
		},
		Summary = "寻找伊格尔"
	},
	[8152] = {
		Title = "梦罗克村居民",
		Description = {
			"你是说有个感觉阴沉沉的、穿着奇怪的衣服的人吗？他的语调很奇怪，好像不是卢恩·米德加兹王国的人……不久前他还在这里，后来说是去看金字塔了。之后我就没再见到过他。我还说那里太危险，劝他不要去，但他还是去了。"
		},
		Summary = "寻找伊格尔"
	},
	[8153] = {
		Title = "伊格尔的口信",
		Description = { "你能帮我转告斯派德拉娜吗？说满月之前，我会回到莫斯科，我想见她一面。告诉她我会变得更强，让她不再？我而痛苦，然后去找她。" },
		Summary = ""
	},
	[8154] = {
		Title = "The Keymaker",
		Description = {
			"The keymaker is at a cabin deep inside of the forest. Beware of the keymaker's words and don't forget the blacksmith's protection spell, \"^0000ffSpellshield Protection^000000\"."
		},
		Summary = ""
	},
	[8155] = {
		Title = "秋天的主人马洛兹卡",
		Description = {
			"在这个洞穴里有“火炉”和“苹果树”。请你把“火炉”里的^0000ff100个烤好的派和“苹果树”上的^0000ff100个熟透的苹果拿出洞穴。向我证明你的能力。"
		},
		Summary = "带着烤好的派和熟透的苹果逃出洞穴"
	},
	[8156] = {
		Title = "秋天的主人马洛兹卡",
		Description = { "不知你知不知道，用黄金做成细而长的线是非常困难的。也需要大量的时间。我现在就开始制作，让我看看……你能一个小时以后再来吗？" },
		Summary = ""
	},
	[8157] = {
		Title = "马洛兹卡的条件",
		Description = {
			"因为你打算帮助玛丽亚？莫雷布纳，科雪伊一定会把你视作敌人。你还是想得到金线吗？好的，我把金线给你！但是你必须答对我出的所有谜题。我不能让你？了我们村子而付出牺牲。这可以说是最基本的考试了。"
		},
		Summary = ""
	},
	[8158] = {
		Title = "破草棚里的芭芭亚卡",
		Description = { "在森林的深处，有一座破草棚。据说草棚的附近有可以制作“金色钥匙”的人。泉水，泉水，洗掉我的痣。这是可以保护自己不受芭芭亚卡伤害的咒语。请你一定要记住。" },
		Summary = ""
	},
	[8159] = {
		Title = "芭芭亚卡的跑腿活",
		Description = {
			"在我制作“金色钥匙”的时间里，你帮我去办一件事！我养的牛跑出去了。你去帮我把它找回来。找到牛之后，在它身上施展返回咒语。“好的饲料橘子香”。好了！快去！慢了的话，我会让你知道厉害！嘻嘻嘻嘻嘻嘻。"
		},
		Summary = "寻找芭芭亚卡的牛"
	},
	[8160] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "念了咒语之后，牛被光芒包围，然后和光芒一起消失了" },
		Summary = "回到芭芭亚卡那里"
	},
	[8161] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "房子后面，有个吵闹的棺材。最近一直在吵，弄得我晚上都睡不着觉。你去帮我安慰它一下。好了！快去！慢了的话，我会让你知道厉害！嘻嘻嘻嘻嘻嘻。" },
		Summary = "安慰吵闹的棺材"
	},
	[8162] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "……再吵一次的话，我就要你好看……" },
		Summary = "回到芭芭亚卡那里"
	},
	[8163] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "帮我找找我的银勺子。它被那些该死的海盗偷走了。我在遇难船的某处感觉到了它的气息。你去帮我找回来。好了！快去！慢了的话，我会让你知道厉害！嘻嘻嘻嘻嘻嘻。" },
		Summary = "找回芭芭亚卡的勺子"
	},
	[8164] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "旧床单的斑点" },
		Summary = ""
	},
	[8165] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "旧床单的斑点，刻着什么的墙壁：他的……小心……听不到的人鱼的歌声……沉睡……的眼神……保护身体的……镜子……" },
		Summary = ""
	},
	[8166] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "旧床单的斑点，刻着什么的墙壁：他的……小心……听不到的人鱼的歌声……沉睡……的眼神……保护身体的……镜子……，折断的钥匙把手" },
		Summary = ""
	},
	[8167] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "旧床单的斑点，刻着什么的墙壁：他的……小心……听不到的人鱼的歌声……沉睡……的眼神……保护身体的……镜子……，折断的钥匙把手，折断的钥匙碎片" },
		Summary = "把折断的钥匙碎片和把手拼起来，拼成了一把钥匙"
	},
	[8168] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "反射的光照在女人的雕像上，箱子冒出了一缕烟，发出喀嚓的声音，然后打开了。发现了芭芭亚卡的银勺子" },
		Summary = "回到芭芭亚卡那里"
	},
	[8169] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "你去帮我买本魔法书。我要天津城的莫莫塔罗出版社出版的书。快去帮我买一本。好了！快去！慢了的话，我会让你知道厉害！嘻嘻嘻嘻嘻嘻。" },
		Summary = "？芭芭亚卡购买魔法书"
	},
	[8170] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "是这本书吗？“打破时间的魔法”、“世界家庭鬼怪故事”、“奇特而奇妙的药草世界”。欢迎光临。如果你需要什么书，请随时和我联系。" },
		Summary = "回到芭芭亚卡那里"
	},
	[8171] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "看到草棚前面的那个坛子了吗？那里面生活着家鬼。你去把它赶走。一直待在这里，烦死人了。好了！快去！慢了的话，我会让你知道厉害！嘻嘻嘻嘻嘻嘻。" },
		Summary = "赶走家鬼"
	},
	[8172] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "以后我会温顺一点，不再危害别人了！我会成为守护这个房子的守护者！你能理解一个家鬼的心，真是个善良的人。我不会忘记你的。再次对你表示感谢。" },
		Summary = "回到芭芭亚卡那里"
	},
	[8173] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "帮我去斐扬的扫帚奶奶那里买把扫帚。斐扬制造的扫帚最好用，但是我没有时间，所以去不了。好了！快去！慢了的话，我会让你知道厉害！嘻嘻嘻嘻嘻嘻。" },
		Summary = "去斐扬买扫帚"
	},
	[8174] = {
		Title = "芭芭亚卡的跑腿活",
		Description = {
			"不久前，我制作的扫帚全都被鬼怪抢走了。虽然连鬼怪们都喜欢我制作的扫帚，我很开心。但被抢走之后……我儿子几次都想去把扫帚找回来，但鬼怪们在树里和他捉迷藏，每次都白跑一趟。"
		},
		Summary = ""
	},
	[8175] = {
		Title = "芭芭亚卡的跑腿活",
		Description = { "啊，认输了吗？不过挺好玩的。我已经玩够了，把说好的扫帚交给你吧。你真是个有趣的人类。下次有机会的话，再来找我玩。这个你拿着吧。" },
		Summary = "回到芭芭亚卡那里"
	},
	[8176] = {
		Title = "金色钥匙",
		Description = { "你来的正好。我把“金色钥匙”做出来了！来，你用它去帮助玛丽亚？莫雷布纳吧。不过要小心科雪伊。嘻嘻嘻嘻嘻嘻。" },
		Summary = "把玛丽亚？莫雷布纳放出来"
	},
	[8177] = {
		Title = "不死之神科雪伊",
		Description = { "啊……现在动手，应该可以救出玛丽亚？莫雷布纳。我会带着玛丽亚？莫雷布纳带走，科雪伊就交给你了！！" },
		Summary = "击败科雪伊"
	},
	[8178] = {
		Title = "活水和死水",
		Description = {
			"玛丽亚还没有死，但是也差不多了。要想救她，需要“活水”和“死水”。芭芭亚卡应该可以救她。我会守着她，不让她死去。请你去芭芭亚卡那里拿回“活水”和“死水”。拜托你了。"
		},
		Summary = "把活水和死水带回来"
	},
	[8179] = {
		Title = "活水和死水",
		Description = {
			"“活水”……我好像听说过。听说可以用^0000ff1个圣水和^0000ff2张构成世界的树叶就可以制作。至于“死水……可以用^0000ff1个诅咒之水和^0000ff10张名叫西纳莱的叶片制作。"
		},
		Summary = "把材料交给芭芭亚卡"
	},
	[8180] = {
		Title = "活水和死水",
		Description = {
			"人类的小孩，你拿着这些东西去帮助玛丽亚？莫雷布纳吧。嘻嘻嘻嘻。首先把“死水”洒在玛丽亚？莫雷布纳身上，消除伤口和诅咒。然后把“活水”洒在她的身上，玛丽亚就会活过来。听懂了的话，就走吧！嘻嘻嘻嘻嘻"
		},
		Summary = "回到玛丽亚？莫雷布纳那里"
	},
	[8181] = {
		Title = "火狩冲击",
		Description = {
			"用它可以把靠近自己的敌人击退到一定距离之外。这说起来容易，但其实是非常困难的。骑士们经常使用这种技能……你去找他们的话，说不定他们会教给你……你去弗伦特拉11点方向的骑士团看看。在那里学习击退技术的原理，然后再来找我。"
		},
		Summary = ""
	},
	[8182] = {
		Title = "击退技术的原理",
		Description = { "还有什么需要的吗？击退技术的原理这种程度已经足够了。至于怎应用，那就是你自己的问题了。" },
		Summary = "回到喵呜那里"
	},
	[8183] = {
		Title = "火狩冲击",
		Description = { "你得先付学习费！这里又不是慈善组织！10个蓝水晶、10个绿色生命和10个红色鲜血！把这些东西交给我。应该不难吧？快去搜集吧。我先在这里睡一觉……啊。" },
		Summary = "搜集材料，交给喵呜"
	},
	[8184] = {
		Title = "元素转化器",
		Description = {
			"要制作元素转化器，需要下列材料。10个蝎子的尾巴、7个坚硬的角、12个花斑甲壳、10个蜗牛壳、4个空卷轴。搜集到所有材料之后，我就会以那些材料？基础，把技能教给你。"
		},
		Summary = "搜集材料，交给米休娜"
	},
	[8185] = {
		Title = "元素转化",
		Description = { "接下去的技能，就是使用转化器，改变怪物的属性的元素转化技能……我先去吃饭，然后再回来。如果你做好了学习技能的准备，请随后再来找我。" },
		Summary = ""
	},
	[8186] = {
		Title = "火属性元素转化",
		Description = {
			"为了刻印对应的属性能力，需要有下列材料。20个红色鲜血、1个斐扬水溶液、1个梦罗克水溶液……请把搜集到的材料交给我，然后我会把火属性元素转化技能教给你。我在这里等着你～"
		},
		Summary = "搜集材料，交给米休娜"
	},
	[8187] = {
		Title = "地属性元素转化",
		Description = {
			"为了刻印对应的属性能力，需要有下列材料。20个绿色生命、1个斐扬水溶液、1个梦罗克水溶液……请把搜集到的材料交给我，然后我会把地属性元素转化技能教给你。我在这里等着你～"
		},
		Summary = "搜集材料，交给米休娜"
	},
	[8188] = {
		Title = "风属性元素转化",
		Description = {
			"为了刻印对应的属性能力，需要有下列材料。20个翠绿之风、1个斐扬水溶液、1个梦罗克水溶液……请把搜集到的材料交给我，然后我会把风属性元素转化技能教给你。我在这里等着你～"
		},
		Summary = "搜集材料，交给米休娜"
	},
	[8189] = {
		Title = "水属性元素转化",
		Description = {
			"为了刻印对应的属性能力，需要有下列材料。20个蓝水晶,1个斐扬水溶液、1个梦罗克水溶液……请把搜集到的材料交给我，然后我会把水属性元素转化技能教给你。我在这里等着你～"
		},
		Summary = "搜集材料，交给米休娜"
	},
	[8190] = {
		Title = "诱惑之波",
		Description = { "美丽可以为女性带来自信。表情控制和形象训练可以说是成功女士的必须要素。好了，你能先去搜集镜子吗？干嘛那样看我？别那样呆呆地看着我，快去啊！" },
		Summary = "把1个水晶制作的镜子交给沙内尔"
	},
	[8191] = {
		Title = "有魅力的建议者",
		Description = { "如果你想向别人展示自己的魅力，就必须学习如何有效地展现自己的魅力。？此，你最好去见见这个方面的专家。我的姐姐在弗伦特拉教堂附近，她应该会给你很多建议。" },
		Summary = ""
	},
	[8192] = {
		Title = "不讲理的建议者",
		Description = {
			"你的眼光还真是差劲。喝东西的话！至少要喝含酒精的东西，不是吗？！如果再机灵一点的话，就应该带着下酒菜过来。你去搜集1个苹果、3个香蕉、5个曲奇，然后装在盘子里带过来。"
		},
		Summary = "搜集酒和下酒菜，交给阿耶尔"
	},
	[8193] = {
		Title = "不讲理的建议者",
		Description = { "你知道怎样才能毫不费力地向对方展现自己的魅力吗？那就是？媚眼。？媚眼！虽然只不过是眨一眨眼睛，但其效果却非常好！可以说是震撼心灵的强烈冲击！！" },
		Summary = ""
	},
	[8194] = {
		Title = "不省人事的建议者",
		Description = { "别吵醒我！！！！快走开！！！" },
		Summary = ""
	},
	[8195] = {
		Title = "亲切的沙内尔",
		Description = { "你是连用勺子吃饭都不愿意，需要人喂到嘴里吗？那种东西，自己好好想想嘛！……我虽然很想这么说，但我是亲切的沙内尔~，让我来告诉你一个秘方吧。" },
		Summary = ""
	},
	[8196] = {
		Title = "三国联合调查团的矛盾",
		Description = {
			"调查员们最近好像有很多不满，烦躁感也到达了顶点。你能去听听他们的话吗？如果可以把问题解决的话，就顺便解决掉！特别是负责文件的调查员之间的矛盾好像很严重。希望你能去他们中间，和他们好好地聊聊。"
		},
		Summary = ""
	},
	[8197] = {
		Title = "传送文件",
		Description = {
			"请你帮我把这些文件交给修巴尔兹巴尔德的文件负责人休和阿鲁纳佩尔茨的文件负责人汉吉纳。如果不先去修巴尔兹巴尔德的话，他们拿这说事。所以请你先去那边吧。然后让他们在下面签上名。"
		},
		Summary = "把文件交给休和汉吉纳，让他们签上名后，回去交给廖森"
	},
	[8198] = {
		Title = "向事务官报告",
		Description = { "就先按照邀请函上的时间安排一下会议吧。你能帮我把这封邀请函拿去交给事务官吗？这段时间我得为会议做一下准备了。" },
		Summary = "把文件交给联合调查团事务官"
	},
	[8199] = {
		Title = "联合调查团事务官的委托",
		Description = {
			"那三个人参加的会议，气氛一定好不到哪里去。所以，希望你也一起参加会议。中间如果发生什么事情的话，也好做个调解。那么！你能再去见见三个人，看看他们有没有在认真地？会议做准备，好吗？"
		},
		Summary = ""
	},
	[8200] = {
		Title = "廖森的数据请求",
		Description = { "之前我向阿鲁纳佩尔茨要了一份数据，但是现在还没送过来。你能帮我去汉吉纳那里拿一下吗？会议就在眼前，可他们好像根本就没打算给我送过来！？" },
		Summary = ""
	},
	[8201] = {
		Title = "遗失的数据",
		Description = { "资料？是廖森让你来的吗？应该是上次玩寻宝游戏的时候掉到桥下去了！用鱼竿钓的话，能钓到吗～？听说西南面的喵呜们正在教人钓鱼。运气好的话，说不定可以钓起来。" },
		Summary = "钓到遗失的文件后，回去找汉吉纳"
	},
	[8202] = {
		Title = "文件复原",
		Description = { "听说修巴尔兹巴尔德好像有修复这种烂掉了的文件的技术……你能去让休帮着修复一下吗？他一定会抱怨，但是应该会帮你的。但是应该会泡泥的。哈哈哈哈哈。哈哈哈哈哈。" },
		Summary = ""
	},
	[8203] = {
		Title = "资料复原",
		Description = {
			"都已经被水泡烂了，先等它晾干一定，把粘在一起的纸弄开之后，然后再开始文字的修正工作。需要准备的东西有^0000ff妙怪的扇子1个，黑色平底锅1个，烈火石1个，墨汁1个。不要用这种眼神看着我。要说的话，我？什么要帮你修复这种文件啊？"
		},
		Summary = "把妙怪的扇子1个，黑色平底锅1个，烈火石1个，墨汁1个交给休"
	},
	[8204] = {
		Title = "把资料交给廖森",
		Description = { "文件整理得太乱，修复的时候我顺便弄得好看了一点。文件整理就应该像这个样子。那两个国家的文件负责人应该看着好好学学！快拿过去给他吧。要不就晚了。" },
		Summary = ""
	},
	[8205] = {
		Title = "向事务官报告",
		Description = { "我再找点其他的数据带过去。你能帮我跟事务官说我在找资料，让他稍微等我一会儿吗？会议马上就要开始了，拜托你了。" },
		Summary = ""
	},
	[8206] = {
		Title = "联合调查团会议",
		Description = { "看着会议进行" },
		Summary = ""
	},
	[8207] = {
		Title = "罪犯不是汉吉纳",
		Description = { "啊，真丢人。本来想让三个人亲近一点的，每次都会出现这样的问题。难道就没有什么办法让三个人和解吗？" },
		Summary = ""
	},
	[8208] = {
		Title = "汉吉纳的委托",
		Description = {
			"不过也不是什么大事，很快就会好起来的。等稍微冷静一点之后，他应该就会知道那不是什么值得生气的事情。不过，我很担心廖森和休两人的关系。你能看情况，进行一下调解吗？当然用意不要太明显。"
		},
		Summary = ""
	},
	[8209] = {
		Title = "休的报告书",
		Description = { "这个，这是刚才我失神的时候不小心拿在手里的卢恩·米德加兹那边的报告书……你能帮我把它拿去还给廖森吗？" },
		Summary = ""
	},
	[8210] = {
		Title = "向事务官报告",
		Description = { "现在不是这样的时候，我得马上重新召开一个会议。我想让刚才会议上没能进行下去的为了和解的努力继续下去……所以，你能帮我去把会议申请交给事务官吗？" },
		Summary = ""
	},
	[8211] = {
		Title = "施兰克的课程",
		Description = {
			"你还没学习狂击啊。连这？基本的东西都不会……不过，你今后的日子还远得很，先慢慢来吧。你先从狂击开始学起吧。不管时代怎变换，剑士的基本技能肯定还是狂击。请你别忘了！"
		},
		Summary = "修炼狂击后，回到施兰克那里"
	},
	[8212] = {
		Title = "施兰克的课程",
		Description = { "嗯，虽然你学会了狂击，但还不熟练。你再去好好练练！我会一直待在这里。" },
		Summary = "修炼狂击技能后，回到施兰克那里"
	},
	[8213] = {
		Title = "施兰克的课程",
		Description = { "哈……狂击的水平已经相当不错了嘛！但是在我看来还是不够。你再去好好练练！我会一直待在这里。" },
		Summary = "修炼狂击技能后，回到施兰克那里"
	},
	[8214] = {
		Title = "施兰克的课程",
		Description = { "哈……狂击已经练满了啊？真了不起。但是自满是不行的。希望你继续精进。现在你只是完成了打基础的过程，今后的路还很长。" },
		Summary = "听取施兰克的课程"
	},
	[8215] = {
		Title = "施兰克的课程",
		Description = { "有关提高HP恢复力的内容，我就说到这里。我想说什么来着？对了，挑衅！关于挑衅，我想？你上一课。在这之前，我还得准备一些东西。你过会儿再来和我说话。" },
		Summary = "听取施兰克的课程"
	},
	[8216] = {
		Title = "施兰克的跑腿活",
		Description = { "请你找到临时去盖佩调查的骑士迪丘，然后转述我的话。^0000FF暗杀者事件怎样了？身份查明了吗？查明了的话，我们该怎办？……就这样转告他就行。" },
		Summary = "找到盖佩的迪丘，转述施兰克的话"
	},
	[8217] = {
		Title = "迪丘的口信",
		Description = {
			"暗杀者事件怎样了？身份查明了吗？查明了的话，我们该怎办？……他让你这么转告我？知道了。帮我这？告诉他。还没有。但应该马上就能查明身份。到时候就拜托了。完毕！"
		},
		Summary = "向伊兹鲁德的施兰克转达迪丘的话"
	},
	[8218] = {
		Title = "施兰克的课程",
		Description = { "嗯……你还没学会挑衅啊。基础虽然重要，但只有熟练使用这些应用技能，才能称得上真正的战士，不是吗？接下去的修炼，请以挑衅为主。" },
		Summary = "修炼挑衅技能后，回到施兰克那里"
	},
	[8219] = {
		Title = "施兰克的课程",
		Description = { "嗯，学是学会了……但还是太弱。这种水平，你都不好意思说自己学会了挑衅。接下去的修炼，请以挑衅为主。" },
		Summary = "修炼挑衅技能后，回到施兰克那里"
	},
	[8220] = {
		Title = "施兰克的课程",
		Description = { "接下去……学什么好呢？对了，我把忍耐^00000教给你。我先出去吹吹风，你一会儿再来找我。" },
		Summary = "听取施兰克的课程"
	},
	[8221] = {
		Title = "施兰克的课程",
		Description = {
			"忍耐，简单地说，就是依靠毅力坚持的技能。即，让你可以自信地说：不管么怎被人打，哈哈，我都一动不动！从现在开始需要修炼忍耐！希望你通过修炼，可以获得不？敌人的攻击所动的坚强的身躯！"
		},
		Summary = "修炼忍耐技能后，回到施兰克那里"
	},
	[8222] = {
		Title = "施兰克的跑腿活",
		Description = { "课程暂时结束。和刚才一样，有件事要交给你。你还记得之前见到过的迪丘吗？你得过去帮他做点事。快去吧。迪丘的事情完成之后，别忘了回我这里一趟……" },
		Summary = "找到迪丘"
	},
	[8223] = {
		Title = "迪丘的跑腿活",
		Description = { "你到梦罗克去，见见那里的<NAVI>[缪特罗]<INFO>morocc,82,292,0,101,0</INFO></NAVI>、<NAVI>[盖尔]<INFO>morocc_in,51,101,0,101,0</INFO></NAVI>、<NAVI>[汉斯]<INFO>morocc,240,72,0,101,0</INFO></NAVI>和<NAVI>[班克利]<INFO>morocc_in,12,156,0,101,0</INFO></NAVI>。然后在他们中间找出真正的刺客！这是我给你的任务。你去和四个人说话，然后回来找我。" },
		Summary = "去梦罗克寻找刺客的证据，然后回到迪丘那里"
	},
	[8224] = {
		Title = "罪犯的线索",
		Description = {
			"扎克达一扎正米见银，吧扎苏达黑其胡亿拉，伊邦一农杀嫩嘎八奥，龙嫩利个安拉格盖堆……这话真奇怪。到底是什么意思呢？你帮我想一想。我根本不知道在说什么。但是我知道，这是抓到罪犯的重要线索。"
		},
		Summary = ""
	},
	[8225] = {
		Title = "迪丘的推理",
		Description = { "罪犯是班克利！那个暗号中只有班克利的名字，而没有缪特罗和汉斯的名字！你快去梦罗克监视<NAVI>[班克利]<INFO>morocc_in,12,156,0,101,0</INFO></NAVI>！有什么事情的话，就通知我！" },
		Summary = "监视梦罗克的班克利"
	},
	[8226] = {
		Title = "班克利之死",
		Description = { "-已经死了。表情看上去充满了怨恨和悲伤。好像死去还没多久，血还没有干。他的胸口有一道深深的伤口，右手握着一把沾血的刀。-" },
		Summary = "向迪丘报告班克利的死讯"
	},
	[8227] = {
		Title = "回到施兰克那里",
		Description = { "嗯……我好像感觉到了阴暗的黑幕，但现在还什么都不知道……知道了。你还有事要干吧？快回到施兰克那里去吧。我再说一遍，这次辛苦你了！" },
		Summary = "回到施兰克那里"
	},
	[8228] = {
		Title = "施兰克的课程",
		Description = { "最后，应该给你说明暴怒了。我得准备一下，请重新和我说话。" },
		Summary = "听取施兰克的课程"
	},
	[8229] = {
		Title = "加宁的课程",
		Description = { "你还没学习商法，还没有达到商人的基本要求……所谓的基本要求……就是名叫持有量增加的技能！请你先讲持有量增加技能升到4。那时我会再对你进行教育。" },
		Summary = "修炼持有量增加技能后，回到加宁那里"
	},
	[8230] = {
		Title = "加宁的课程",
		Description = { "下面，我来？你介绍和物品鉴定一样的基本技能金钱攻击。在这之前，你先休息一下！喘口气，然后再来和我说话。" },
		Summary = "听取加宁的课程"
	},
