	[8247] = {
		Title = "调查研究情况",
		Description = { "我会把宝石中记录的声音提取出来，然后交给阿鲁纳佩尔茨的语言学家。如果你没事的话，能帮我去确认一下阿鲁纳佩尔茨语言学家的研究情况吗？" },
		Summary = ""
	},
	[8248] = {
		Title = "调查研究情况",
		Description = { "这下异界语言的解读工作就容易多了。但问题是，是不是真的能制作出包含这么多信息的翻译机……你能去问问修巴尔兹巴尔德的机械工程师的意见吗？" },
		Summary = ""
	},
	[8249] = {
		Title = "信息储存方法",
		Description = { "通过卢恩·米德加兹的魔法，好像用魔力将信息注入到宝石之中……我想去向卢恩·米德加兹的魔法学家请教一下。你能帮我去问一下吗？" },
		Summary = ""
	},
	[8250] = {
		Title = "异界的矿石",
		Description = {
			"听说在远征队营地的外面，在寒冷的地区，有一种在^0000ff米德加尔特无法搜集到的神奇矿石。如果能弄到那种矿石，我应该可以想想办法……你能帮我去搜集一颗那样的矿石吗？"
		},
		Summary = "将未确认的矿石交给卢恩·米德加兹魔法学家"
	},
	[8251] = {
		Title = "魔力注入",
		Description = { "你能稍等一下吗？我得把矿石加工成宝石，然后把魔力的信息注入其中。请你在这段时间休息一下，你看上去好像有点累……" },
		Summary = ""
	},
	[8252] = {
		Title = "加工好的宝石",
		Description = { "最后我还得麻烦你一下。请你帮我把加工好的宝石交给修巴尔兹巴尔德的机械学家。" },
		Summary = ""
	},
	[8253] = {
		Title = "异界语言翻译机",
		Description = { "必须制作出可以从宝石中读取魔力的机械装置才行。准备工作都已经完成，大概再过一个小时应该就能做好了。" },
		Summary = "一小时后，回去找修巴尔兹巴尔德机械学家"
	},
	[8254] = {
		Title = "静修身体和心灵",
		Description = { "在转职成为游侠之前还需要经过一个步骤，虽然你达到了猎人的最高境界，但这是不是全靠一身好装备呢～？为了避免这种情况，我必须对你真正的能力进行评价～" },
		Summary = "将重量清空为0后，和龟岛的瑞斯可对话"
	},
	[8255] = {
		Title = "生存能力考试",
		Description = { "通过最基本的生存能力考试之后，你就能获得参加实战考试的资格～详细的情况等你获得实战考试的资格之后再说～如果你想参加生存能力考试，请再和我说话。" },
		Summary = "和龟岛的瑞斯可对话"
	},
	[8256] = {
		Title = "生存能力考试",
		Description = { "你带着我给你的东西，^0000ff找到乌龟岛11点方向，也就是西北方向的实战考试馆，这就是生存能力考试的内容～你没有什么装备，一定要小心那里的怪物～" },
		Summary = "找到龟岛11点方向的术科考官"
	},
	[8257] = {
		Title = "提耶德鲁的筹备粮食",
		Description = {
			"生存下去的最基本的方法是让自己的身体变得更强，但在粮食供应困难的情况下，如何搜集粮食不也是生存能力的一部分吗？你先去乌龟岛抓1只^0000ff刺尾蜻蜓，搜集^0000ff1个蜻蜓的翅膀。"
		},
		Summary = "捕捉1只刺尾蜻蜓，搜集1个蜻蜓翅膀，交给龟岛的提耶德鲁"
	},
	[8258] = {
		Title = "提耶德鲁的粮食筹备",
		Description = { "好，这样一来你就有参加实战考试的资格了。在我说明之前，你能先把蜻蜓的翅膀给我吗？俗话说的好，人是铁，饭是钢。" },
		Summary = "和龟岛的提耶德鲁对话"
	},
	[8259] = {
		Title = "前往游侠实战考场",
		Description = {
			"实战考试总共由三个部分组成，进入考场之后会有一个准备要员在里面等着你。你进入准备要员创建的房间，然后等待。考试是单独进行的，人多的话可能得等一会儿，祝你好运。希望你能顺利成为游侠。"
		},
		Summary = "通过龟岛的提耶德鲁进入实战考场，进行三项考试"
	},
	[8260] = {
		Title = "任务！递送文件",
		Description = { "请你把这些档案交给柯吴先监考官，我给他的话他大概不会收……" },
		Summary = "第2项考试，把档案交给柯吴先监考官"
	},
	[8261] = {
		Title = "吹响笛子，狼就会出现！",
		Description = { "第3项考试的内容是测试你是否能熟练地控制成为游侠之后所获得的狼！yeah-yo！你先拿着狼笛，把狼召唤出来之后，再来和我说话yo！" },
		Summary = "用拿到的笛子召唤出狼后，和第3项术科考官普立兹对话"
	},
	[8262] = {
		Title = "游侠大师奈博",
		Description = {
			"祝贺你！祝贺你通过了艰难的实战考试！你已经累积了足够的经验，就没有必要再拖下去了。在转职之前，请先^0000ff解除猎鹰，并确认一下^0000ff职业技能点数有没有全加上去了。"
		},
		Summary = "解除猎鹰，把所有职业技能点数加上去后，和游侠大师奈博对话"
	},
