	},
	[8682] = {
		Title = "前往教国 (2)",
		IconName = "ico_ep.bmp",
		Description = {
			"拉赫的气氛比以前来的时候要险恶得多。当在听某人演讲时，观众之间发生了争吵， <NAVI>[一个人]<INFO>rachel,183,170,0,101,0</INFO></NAVI>引起了注意。"
		},
		Summary = "与神官对话"
	},
	[8683] = {
		Title = "请阻止争执",
		IconName = "ico_ep.bmp",
		Description = { "焦躁的神官请求阻止争执，该怎么办呢？" },
		Summary = "与神官对话"
	},
	[8684] = {
		Title = "先告一段落",
		IconName = "ico_ep.bmp",
		Description = {
			"掩饰不住焦躁的神官朱诺克说要告知目前阿卢纳贝兹状况，约定在 <NAVI>[神殿前]<INFO>ra_temple,72,54,0,101,0</INFO></NAVI>见面。"
		},
		Summary = "前往神殿"
	},
	[8685] = {
		Title = "神殿内检测到可疑动静",
		IconName = "ico_ep.bmp",
		Description = {
			"从朱诺克神官和治安官那里听说最近瑟斯隆尼勒有入侵者出现的令人不安的消息后，马上就收到消息说在 <NAVI>[神殿西侧]<INFO>ra_temple,30,142,0,101,0</INFO></NAVI>有可疑的人出现。"
		},
		Summary = "跟随治安队员"
	},
	[8686] = {
		Title = "神殿的入侵者",
		IconName = "ico_ep.bmp",
		Description = { "似曾相识的他们竟是邪心猎人。看来他们还没有听到入侵宅邸的人被消灭的消息。" },
		Summary = "与神官对话"
	},
	[8687] = {
		Title = "明明毁掉了？",
		IconName = "ico_ep.bmp",
		Description = {
			"奇怪的是邪心猎人的力量很弱。还没觉得可疑，这戏剧性的瞬间就结束了，似乎知道他们是谁的治安队员推荐去见<NAVI>[尼乐研]<INFO>ra_temin,173,40,0,101,0</INFO></NAVI>。"
		},
		Summary = "与尼乐研对话"
	},
