	[8718] = {
		Title = "朋友的问候",
		IconName = "ico_ep.bmp",
		Description = { "灰狼村的阿尔贝担心目前在拉赫酒店工作的朋友<NAVI>[胡林]<INFO>ra_in01,388,59,0,101,0</INFO></NAVI>。" },
		Summary = "与胡林对话"
	},
	[8719] = {
		Title = "蚂蚁地狱某处的新区域",
		Description = { "在蚂蚁地狱2层侦查中的米尔科和尤兰达发现了一处新的蚂蚁洞穴。但是那个地方……" },
		Summary = "与米尔科对话"
	},
	[8720] = {
		Title = "米尔科的拜托 (1)",
		Description = { "米尔科说冒险家同伴布里亚森现在下落不明。布里亚森去前不久发现的认知的庭院探险后没有回来。" },
		Summary = "与米尔科对话"
	},
	[8721] = {
		Title = "布里亚森在哪里",
		Description = { "需要在认知的庭院找到布里亚森。希望她还活着。" },
		Summary = "与布里亚森对话"
	},
	[8722] = {
		Title = "布里亚森的口信",
		Description = {
			"布里亚森说现在还不能回去，让我帮忙转达给 <NAVI>[米尔科]<INFO>anthell02,177,190,0,101,0</INFO></NAVI>她很安全。她奇怪的正常。"
		},
		Summary = "与米尔科对话"
	},
	[8723] = {
		Title = "米尔科的拜托 (2)",
		Description = { "放弃将布里亚森从认知的庭院带出来的米尔科，希望让我帮助布里亚森。" },
		Summary = "与布里亚森对话"
	},
	[8724] = {
		Title = "卡赫里斯在哪里",
		Description = { "虽然很想正常的理解与布里亚森的对话，但是不太对劲。她希望帮忙找到与自己长得相似的卡赫里斯…… " },
		Summary = "与长得与布里亚森相似的冒险家对话"
	},
	[8725] = {
		Title = "一模一样的……？ (1)",
		Description = { "叫勒韦拉的游侠正在找布里亚森。但是布里亚森找的人不是这个名字吧……？告知她，勒韦拉直接消失了。" },
		Summary = ""
	},
	[8726] = {
		Title = "一模一样的……？ (2)",
		Description = { "叫卡赫里斯的游侠说正在找同伴，但是她说在洞穴里迷路的应该是布里亚森……？我告知她这和布里亚森说的有出入，卡赫里斯直接消失了。" },
		Summary = ""
	},
	[8727] = {
		Title = "一模一样的……？ (3)",
		Description = { "叫卡赫里斯的神枪手正在找她的同伴。但是布里亚森找的卡赫里斯是游侠呀……？告知卡赫里斯，她直接消失了。" },
		Summary = ""
	},
	[8728] = {
		Title = "卡赫里斯是谁？",
		Description = {
			"在认知的庭院遇到的与布里亚森相似的人，貌似都不是人。先去找 <NAVI>[米尔科]<INFO>anthell02,177,190,0,101,0</INFO></NAVI>报告下吧。"
		},
		Summary = "与米尔科对话"
	},
	[8729] = {
		Title = "布里亚森在哪里 (2)",
		Description = { "卡赫里斯可能是黑蚁。它的意图是……？接近布里亚森的目的是？在这云里雾里的情况下，米尔科再次拜托我去认知的庭院救助布里亚森。" },
		Summary = "再次进入幻影"
	},
	[8730] = {
		Title = "认知迷宫",
		Description = { "看到了真正的卡赫里斯，告诉米尔科好像是蚂蚁他很是不安。首要的任务还是要现将在认知的庭院里的布里亚森带出来。" },
