	[11058] = {
		Title = "胆小的少年米哈尔",
		Description = { "我的儿子米哈尔，在我不在家的时候把我心爱的俄罗斯套娃弄坏了。也许是怕我打他，所以离家出走了，一直没有回来。" },
		Summary = "寻找米哈尔。他应该没有离开村子。"
	},
	[11059] = {
		Title = "胆小的少年米哈尔",
		Description = { "嘻嘻，那个家伙是个傻瓜，所以没有朋友。不过村里人就数^3131FF苹果树旅馆的主人^000000对他很好。" },
		Summary = "去唯一的线索——苹果树旅馆看看。"
	},
	[11060] = {
		Title = "胆小的少年米哈尔",
		Description = { "客人的话我就可以告诉你，就这样告诉过路的旅客，我岂不是会很吃亏？如果你答应在我们旅馆住一天，我就把你想要的信息告诉你。怎样？" },
		Summary = "在旅馆住一天，然后向旅馆主人询问米哈尔的下落。"
	},
	[11061] = {
		Title = "胆小的少年米哈尔",
		Description = { "不知道他打碎了什么重要的东西，脸色看上去有点发青，说需要强力胶水。酒店里有很多男人，他说要去那边看看。" },
		Summary = "米哈尔好像去了酒店。去酒店寻找米哈尔。"
	},
	[11062] = {
		Title = "胆小的少年米哈尔",
		Description = { "我不知道什么胶水。不过我知道有个这方面的专家，所以就介绍他去了。就是酒店角落里的那个男人——维克托。" },
		Summary = "米哈尔好像不在酒店里。去问问酒店主人介绍的。"
	},
	[11063] = {
		Title = "胆小的少年米哈尔",
		Description = { "来，这是您要的饮料。祝您过得愉快。" },
		Summary = "喝掉饮料，试着接近维克托。"
	},
	[11064] = {
		Title = "胆小的少年米哈尔",
		Description = { "要想制作强力胶水，必须坐很长时间的船去沼泽搜集材料。难道弄坏了俄罗斯套娃就害怕得不行的孩子，有勇气去那种可怕的地方？" },
		Summary = "米哈尔到底去哪儿了呢？要去沼泽看看吗？"
	},
	[11065] = {
		Title = "胆小的少年米哈尔",
		Description = { "看着就让人起鸡皮疙瘩的巨大的沼泽。到处泛着黑色的气泡，让人觉得很可怕。" },
		Summary = "没发现有人来过的痕迹。先到米哈尔的家里去看看吧。"
	},
	[11066] = {
		Title = "胆小的少年米哈尔",
		Description = { "回到家里之后，发现米哈尔躲藏在壁炉里。搜集胶水，帮他把俄罗斯套娃粘好。" },
		Summary = "向溪水酒店的维克托询问胶水的材料。"
	},
	[11067] = {
		Title = "胆小的少年米哈尔",
		Description = {
			"莫斯科附近有个巨大的岛。在那里的森林深处，可以看到一片沼泽。你去沼泽采集^3131FF“10个嗖嗖草”^000000，然后再找^3131FF1个药碗^000000给我。千万别忘了。"
		},
		Summary = "采集10个嗖嗖草，交给维克托。别忘了还要一个药碗！"
	},
	[11068] = {
		Title = "胆小的少年米哈尔",
		Description = { "来，做好了！我已经把胶水给你了，你可以不再烦我了吧？快走吧！" },
		Summary = "获得了胶水。回去交给米哈尔。"
	},
	[11069] = {
		Title = "胆小的少年米哈尔",
		Description = { "好了，我去把俄罗斯套娃还给妈妈。" },
		Summary = "米哈尔从壁炉里走了出来。回去见见嘉莉亚。"
	},
	[11070] = {
		Title = "毒药王",
		Description = { "毒功？你想学了干嘛？毒药的知识，我已经忘记好久了。你去见见我唯一的徒弟^0000FF“宋剧毒”^000000，说不定他知道。" },
		Summary = "向在药房仓库工作的宋剧毒询问毒功的事情。"
	},
	[11071] = {
		Title = "毒药王",
		Description = { "够了。你走吧。明明知道前因后果，还跟我说这种话，我生气了。" },
		Summary = "宋剧毒发火了。有什么让他消气的方法呢？"
	},
	[11072] = {
		Title = "毒药王",
		Description = { "如果你觉得这？抱歉的话，就参加到我的复仇之中吧。我需要^0000FF4个黄蜂毒针、10个毒牙、10个空药瓶、30个绿色药水^000000。" },
		Summary = "搜集材料，交给宋剧毒。"
	},
	[11073] = {
		Title = "毒药王",
		Description = { "毒药提炼成功的话，我想把它交给理解我的愤怒的人。我的身体太弱，没办法潜入什么地方……" },
		Summary = "重新对话，接受宋剧毒的委托。"
	},
	[11074] = {
		Title = "毒药王",
		Description = { "手续费拿到了！来，给你～好了～再见～" },
		Summary = "拿到了委托的东西。回去见见宋剧毒。"
	},
	[11075] = {
		Title = "毒药王",
		Description = { "啊……又失败了。真是……准备好的材料全都消失了……" },
		Summary = "制造失败！好像需要新的材料。"
	},
	[11076] = {
		Title = "毒药王",
		Description = {
			"下面是最后一件事。请你带着刚才的毒药到龙之城去，潜入太守所在的地方，把毒药撒在他会碰到的对方。^0000FF师傅^000000知道我完成了他理想中的毒药的话，一定会高兴得跳起来的！"
		},
		Summary = "该怎办好呢？"
	},
	[11077] = {
		Title = "毒药王",
		Description = { "发现了太守心爱的酒瓶，在那里下了毒。" },
		Summary = "执行了宋剧毒的委托。回到他那里。"
	},
	[11078] = {
		Title = "毒药王",
		Description = { "我已经跟你说明了所有的情况。我的徒弟宋剧毒制作致命毒药的理由，以及他对太守的复仇心和憎恶。" },
		Summary = "他好像需要一些思考的时间。"
	},
	[11079] = {
		Title = "毒药王",
		Description = { "必须……阻止……我的徒弟。除了你之外，我还拜托过很多人……" },
		Summary = "找到太守心爱的酒瓶，并拿掉它。"
	},
	[11080] = {
		Title = "毒药王",
		Description = { "你偷走了酒瓶，并在那里放上了粘稠的液体。" },
		Summary = "成功地偷到了酒瓶。回到纳加西？阿尔塞斯那里。"
	},
	[11081] = {
		Title = "毒药王",
		Description = { "来……这，这是……交给太守的……书信，里面包含了……老夫被关押的15年间……老夫的错误……太守的错误……还有真相……" },
		Summary = "把纳加西？阿尔塞斯的信交给太守。"
	},
	[11082] = {
		Title = "毒药王",
		Description = { "谢谢你！告诉了我真相！这是我的一点诚意，请你收下。还有，帮我把这个……交给纳加西和宋剧毒。" },
		Summary = "转交了书信。把白龙的书信交给纳加西。"
	},
	[11083] = {
		Title = "毒药王",
		Description = { "……谢谢你，年轻人。" },
		Summary = "纳加西好像很满足。向宋剧毒转达消息。"
	},
	[11084] = {
		Title = "适应新环境的方法",
		Description = { "如果你是新来的话，就先去见见^0000FF卢根教官^000000。这对你尽快适应这里的环境会有所帮助。你一直往右走，就能见到^0000FF卢根教官☆了。" },
		Summary = "去见见卢根教官。"
	},
	[11085] = {
		Title = "适应新环境的方法",
		Description = { "注册手续非常简单。你只要到中央的巨大建筑那里，和注册员说一声就可以了。" },
		Summary = "去中央建筑注册。"
	},
	[11086] = {
		Title = "适应新环境的方法",
		Description = { "" },
		Summary = "在死板的注册员那里完成了注册。回去见见卢根教官。"
	},
	[11087] = {
		Title = "修理营舍",
		Description = {
			"驻地西边有一片树林，去那里找些合适的树枝回来吧。绳子嘛，在驻地的东边，有一种叫做^0000FF猪笼草^000000的神奇植物，大家都说那种植物的茎杆很坚韧。"
		},
		Summary = "搜集^0000FF20个普通的树枝和20个结实的藤^000000，回去交给迪艾格。"
	},
	[11088] = {
		Title = "修理营舍",
		Description = { "那就麻烦你帮我把这根柱子用树枝和猪笼草绳子固定起来吧。" },
		Summary = "帮助迪艾格修理柱子。"
	},
	[11089] = {
		Title = "修理营舍",
		Description = { "这边的柱子好像已经固定好了。那边的柱子也麻烦你一下。" },
		Summary = "修好了一根柱子。再修理其他柱子。"
	},
	[11090] = {
		Title = "修理营舍",
		Description = { "断了的柱子完全修好了！" },
		Summary = "柱子修理完成。回去和迪艾格说话。"
	},
	[11091] = {
		Title = "发送配给品",
		Description = { "分配国内送来的配给物品的事情，不是很难，就当是借机会认识认识驻地的同伴们吧。你先去找^0000FF你刚来驻地时遇到的玛丽安^000000去取回配给物品吧。" },
		Summary = "去玛丽安那里取回配给品。"
	},
	[11092] = {
		Title = "发送配给品",
		Description = { "" },
		Summary = "获得了配给品。回到卢根那里。"
	},
	[11093] = {
		Title = "发送配给品",
		Description = { "^0000FF第一个箱子是要递送给驻地西北部的扎安的东西。^000000她大概会在篱笆附近。" },
		Summary = "把第一个箱子送给扎安。"
	},
	[11094] = {
		Title = "发送配给品",
		Description = { "赶紧打开看看~帮我向教官说谢谢哦~哈哈哈" },
		Summary = "把配给品送给了扎安。回到路跟那里。"
	},
	[11095] = {
		Title = "发送配给品",
		Description = { "^0000FF第二个箱子是要递送给杰拉尔的东西。^000000他在驻地外围西侧的桥那边做调查。" },
		Summary = "配送第二个箱子。"
	},
	[11096] = {
		Title = "发送配给品",
		Description = { "你就转告卢根，我一时半会儿是回不去的。" },
		Summary = "把配给品送给了杰拉尔。回到路跟那里。"
	},
	[11097] = {
		Title = "发送配给品",
		Description = { "^0000FF最后的箱子是要送去给东边旷野入口处的阿尔贝托的东西。^000000也许……我听说他订的似乎是厚重的衣物，那一带相当寒冷，你还是尽快送去吧。" },
		Summary = "配送最后一个箱子。"
	},
	[11098] = {
		Title = "发送配给品",
		Description = { "请你转告教官，我还没被冻死。吸鼻涕" },
		Summary = "把配给品送给了阿尔贝托。回到路跟那里。"
	},
	[11099] = {
		Title = "给好友送信……",
		Description = { "我的朋友是在^0000FF西边防御壁上工作的奥托^000000。那就拜托你了。" },
		Summary = "向奥托问安，并转交卢根的信。"
	},
	[11100] = {
		Title = "给好友送信……",
		Description = { "那就麻烦你把我的回信和我很好的消息一起带回去吧。而且不久我大概就能休假了，帮我告诉他，我会去看他的。" },
