	[11173] = {
		Title = "弗烈德的请托",
		Description = { "一直麻烦你真不好意思，可以请你替我带钸镭去给我的同伴们吗？你去拜托位在村落西北方大楼的护卫先生，他就会给你精制钸镭的！万事拜托！" },
		Summary = "去找护卫拿精制钸镭"
	},
	[11174] = {
		Title = "存量不足",
		Description = {
