		NpcPosY = 36,
		RewardEXP = "9600"
	},
	[12073] = {
		Title = "狩猎玩具士兵",
		Description = { "玩具娃娃竟然会袭击人类，很不可思议对吧？你去教训教训他们，15只应该就差不多了。" },
		Summary = "狩猎15只玩具士兵"
	},
	[12074] = {
		Title = "狩猎库克雷",
		Description = { "海底深处好像发生了窃盗案件，库克雷是最可疑的嫌疑犯，请去狩猎30只" },
		Summary = "狩猎30只库克雷"
	},
	[12075] = {
		Title = "狩猎兽人婴儿",
		Description = { "兽人的数量在逐渐增多，虽然有点残忍，但应该把他们的下一代除掉，你自己看着办吧。" },
		Summary = "狩猎15只兽人婴儿"
	},
	[12076] = {
		Title = "狩猎兽人战士",
		Description = { "光靠狩猎兽人婴儿来调节兽人的数量好像还是不够，你能去消灭一些兽人战士吗？大概20个左右就行了。" },
		Summary = "狩猎20个兽人战士"
	},
	[12077] = {
		Title = "狩猎螃蟹",
		Description = { "你见过长着厚厚的壳的蟹吗？它们就是螃蟹。请你去狩猎15只。" },
		Summary = "狩猎15只螃蟹"
	},
	[12078] = {
		Title = "狩猎邪骸食人鱼",
		Description = { "经常捞上来一些死鱼让渔夫们很头疼，他们让我们帮忙处理。不好意思，你能去狩猎30条邪骸食人鱼吗？" },
		Summary = "狩猎30条邪骸食人鱼"
	},
	[12079] = {
		Title = "狩猎乌贼",
		Description = { "你能去狩猎一些乌贼吗？详细的栖息地还不太清楚，相信你应该能找得到，请狩猎15只" },
		Summary = "狩猎15只乌贼"
	},
	[12080] = {
		Title = "狩猎卡那多斯",
		Description = { "这个城市的高官在经过海边的时候被卡那多斯伤到脚，因此下令消灭它们，请去狩猎20只" },
		Summary = "狩猎20只卡那多斯"
	},
	[12081] = {
		Title = "狩猎麦斯特",
		Description = { "最近因为幽灵四处出没，使人们非常恐惧。那些麦斯特的幽灵好像是没有形体，你能去消灭15个吗？" },
		Summary = "狩猎15个麦斯特"
	},
	[12082] = {
		Title = "狩猎贝壳魔灵",
		Description = { "我们收到一个匿名的委托，要狩猎30个贝壳魔灵，但不希望我们过问理由，拜托你啰。" },
		Summary = "狩猎30个贝壳魔灵"
	},
	[12083] = {
		Title = "狩猎气泡虫",
		Description = { "气泡虫？你知道气泡虫是什么吗？我们接到了消灭它们的任务，请你去消灭15只气泡虫" },
		Summary = "狩猎15只气泡虫"
	},
	[12084] = {
		Title = "狩猎剑鱼",
		Description = { "有人想吃好吃的生鱼片，所以委托我们狩猎20条剑鱼。你能帮忙处理一下吗？" },
		Summary = "狩猎20条剑鱼"
	},
	[12085] = {
		Title = "狩猎邪骸兽人",
		Description = { "死去的兽人又复活了，让国王很头疼，虽然出动军人们去讨伐他们，但好像人数不够，你愿意参加吗？只要狩猎15个就行了" },
		Summary = "狩猎15个邪骸兽人"
	},
	[12086] = {
		Title = "狩猎兹诺克",
		Description = { "我们收到了任务，要狩猎30个名叫兹诺克的奇怪生物。你想试试吗？" },
		Summary = "狩猎30个兹诺克"
	},
	[12087] = {
		Title = "狩猎木乃伊",
		Description = { "这是个可怕的任务，需要狩猎15个木乃伊。呃～好可怕，我不想去，还是你去吧。" },
		Summary = "狩猎15个木乃伊"
	},
	[12088] = {
		Title = "执行委托中",
		Description = { "正在执行委托布告栏中的委托" },
		Summary = "执行委托中"
	},
	[12090] = {
		Title = "可疑的男子",
		Description = { "有个叫廖达的男子似乎知道一些重要事情，再跟他谈一下好了" },
		Summary = "可疑的男子"
	},
	[12091] = {
		Title = "找燃烧的心脏",
		Description = { "廖达要求燃烧的心脏，在答应他要求之前应该不会告诉我实情" },
		Summary = "找燃烧的心脏"
	},
	[12092] = {
		Title = "继续对话",
		Description = { "廖达想要的燃烧心脏都已经交给他了，我们来听听他说什么吧！" },
		Summary = "继续对话"
	},
	[12093] = {
		Title = "情报员留给廖达的记录",
		Description = {
			"我们在克雷斯特汉姆修道院内部的某个地方注入了可以侦测皇家卫士痕迹的神圣气息，假如^008855[他]^000000是被选择的人的话，就能侦测到我们所留下的气息，否则就像我们一样不会知道"
		},
		Summary = "情报员留给廖达的记录"
	},
	[12094] = {
		Title = "毁损盾牌的文字",
		Description = { "你是……神圣的力量……看不清句子……被选择的人……王的最后……古城……黑暗的庭院……背对太阳的地方……透出光线……树底下……盾牌的真正主人……会磕头。" },
		Summary = "判读困难"
	},
	[12096] = {
		Title = "去找加拉加斯",
		Description = { "去找位于吉芬塔中央处的加拉加斯" },
		Summary = "去找加拉加斯"
	},
	[12097] = {
		Title = "基本准备",
		Description = { "加拉加斯需要火灵矿石、风灵矿石、地灵矿石、水灵矿石等各3个" },
		Summary = "基本准备"
	},
	[12098] = {
		Title = "4地方的洞穴",
		Description = { "去找设置在冰洞穴、托尔火山洞穴、妙勒尼废弃矿场、昆仑迷宫等四个地方的精灵侦测棒后，使用准备好的属性石，请务必备妥充足的数量，以免多跑几趟哦！" },
		Summary = "4地方的洞穴"
	},
	[12099] = {
		Title = "治本之道",
		Description = { "这是个小小的委托，根据报告推测，天地树根附近的幼龙，是从周围的蛋里孵出来的。虽然消灭幼龙固然重要，但为了治本是绝对不能小看这委托，所以请多加费心。" },
		Summary = "消灭暴躁龙蛋10个-向狩猎1课负责人报告处理结果"
	},
	[12100] = {
		Title = "恐怖飞虫",
		Description = { "最近在守护精灵基地附近，常听到有关以前从未发现过的大型飞虫的消息。若放着不管的话，它们栖息的范围不知道会扩增到哪儿，所以快去将它们消灭吧！" },
		Summary = "消灭鲁修拉黄蜂12个-向狩猎1课负责人报告处理结果"
	},
	[12101] = {
		Title = "妨碍工作",
		Description = {
			"这是在钸镭矿坑工作的同事们，最近经常报告的内容。听说栖息在天地树根附近的幼龙，经常破坏矿坑周围的地基，看样子不能再放任它们不管，请去消灭天地树附近的幼龙吧！"
		},
		Summary = "消灭暴躁龙5个-向狩猎1课负责人报告处理结果"
	},
	[12102] = {
		Title = "有智能的蛇",
		Description = {
			"听说在守护精灵基地附近的沼泽地发现了叫那迦的新种族。问题是他们具有原始的智能，且性格残暴。要是他们的部落扩张的话，那问题会更严重，请去消灭已经成形的那迦吧！"
		},
		Summary = "消灭那迦10个-向狩猎1课负责人报告处理结果"
	},
	[12103] = {
		Title = "传说中的动物",
		Description = { "一直有报告指出，在守护精灵族的根据地附近，发现传说中的白色飞马。请你亲自去确认真假好吗？当然也有可能是幻觉，因此你必须亲手确认，它是否真的为活生生的生物。" },
		Summary = "消灭独角飞马1个-向狩猎1课负责人报告处理结果"
	},
	[12104] = {
		Title = "大胃王昆虫",
		Description = {
			"先不说名为突变蜈蚣的生物有繁殖力，光是它们的巨大食量就足以威胁到我们的生存了。它们会吸收钸镭矿物，使我们的矿坑地区遭受莫大的损失。至今已有几十名的邪派同伴遭到它们的攻击，请你去消灭突变蜈蚣吧！"
		},
		Summary = "消灭突变蜈蚣15个-向狩猎1课负责人报告处理结果"
	},
	[12105] = {
		Title = "活动岩石",
		Description = { "收到矿坑的钸镭原石会活动的消息。可能是钸镭原石受古代咒术而巨人化，如今连矿坑都快要废弃了，请你去消灭它们好吗？" },
		Summary = "消灭钸镭巨人10个-向狩猎1课负责人报告处理结果"
	},
	[12106] = {
		Title = "花上的小鬼头",
		Description = {
			"听说我们派去守护精灵阵营的侦察兵，遭到外表像可爱小鬼头的生物体攻击。因此，不可避免的，必须有人去对付那些家伙，但因为那里是守护精灵的领域，所以身为第3者的你最适合不过了。"
		},
		Summary = "消灭捕虫堇妖15个-向狩猎2课负责人报告处理结果"
	},
	[12107] = {
		Title = "变调的纯情",
		Description = {
			"你知道一种外表像小鬼头，名叫捕虫堇妖的花吗？有消息说它产生变种。因为不仅粗暴又具攻击性，所以守护精灵种族也为歼灭它们而派兵的样子，请你在它们拓展栖息地前，将他们消灭吧！"
		},
		Summary = "消灭突变捕虫堇妖10个-向狩猎2课负责人报告处理结果"
	},
	[12108] = {
		Title = "危险的割草路",
		Description = {
			"去采集矿石的同伴失踪了，不管怎么看都像是猪笼草做的。它和你们人类称为曼陀罗魔花的东西类似，就这么放着不管的话，可能还有许多人会因此受伤，必须要处理一下才行。"
		},
		Summary = "消灭猪笼草12个-向狩猎2课负责人报告处理结果"
	},
	[12109] = {
		Title = "消灭幼虫",
		Description = {
			"似乎发现了突变蜈蚣幼虫聚集的栖息地，若是在成虫前消灭它们，相信可以将它们的数量减少许多。你愿意去消灭它们吗？当然，突变蜈蚣妈妈可能就在附近，你要千万要小心！"
		},
		Summary = "消灭突变蜈蚣幼虫14个-向狩猎2课负责人报告处理结果"
	},
	[12110] = {
		Title = "水恶灵",
		Description = {
			"收到报告指出，在挖掘通往尼德霍格巢穴的矿脉时，遭到奇怪生物的袭击。听说那家伙外表和人体相似的水，但不同于水精灵，它是属于邪恶的一方。那里可能是尼德霍格的发源地，请你去那里确认一下。"
		},
		Summary = "消灭水精灵7个-向狩猎2课负责人报告处理结果"
	},
	[12111] = {
		Title = "丑八怪鸟",
		Description = {
			"名为塔塔丘的鸟，原本是在天上飞，美丽窈窕的鸟，但自从在没有天敌的这里定居后，就变得又胖又懒惰。所以才会成为现在这副吓人的模样，要是你的话，一定可以成为塔塔丘的优蜂蜜天敌。"
		},
		Summary = "消灭塔塔丘10个-向狩猎2课负责人报告处理结果"
	},
	[12117] = {
		Title = "凋谢的花",
		Description = {
