	[12227] = {
		Title = "小归小却很难缠……",
		Description = { "听说在彩虹桥进行采集作业的冒险家遭到体型小的鸟类攻击，它们应该没那么坏呀……不管怎么样，有冒险家委托，所以要请你去处理一下。" },
		Summary = "消灭恶魔啄木鸟5-完毕后向象象报告"
	},
	[12228] = {
		Title = "无法理解的仇恨",
		Description = { "虽然有点不忍心，但这是一个要求消灭顽皮精灵的匿名委托，我是不知道他们有什么仇啦，不过委托就是委托，麻烦你去处理啰！" },
		Summary = "消灭玩偶魔妖6-完毕后向象象报告"
	},
	[12229] = {
		Title = "金毛怪",
		Description = { "要是我说有金色的毛怪到处滚来滚去你相信吗？应该不信吧！虽然外表看起来无害，但是它们会偷走冒险家的书和甜食。请你去处理一下吧！" },
		Summary = "消灭异形毛毛怪7-完毕后向象象报告"
	},
	[12230] = {
		Title = "哈查的委托",
		Description = { "已经从哈查那接受委托。" },
		Summary = "24小时后才可再次接受委托。",
		CoolTimeQuest = 1
	},
	[12231] = {
		Title = "防腐剂的材料",
		Description = {
			"这里的冒险家在出发去迷宫探险前，必须拿到要洒在紧急粮食上的防腐剂，你知道防腐剂的制作材料是什么吗？呵呵~就是昆虫触角哦~那边的杂货商刚好要4个！要是我才不吃这种东西呢~"
		},
		Summary = "收集昆虫触角4-向杂货商报告"
	},
	[12232] = {
		Title = "抵抗的象征",
		Description = { "这里的冒险家喜欢制作符咒确保自身安全，也算是一种保险吧！最近不死心脏好想很受欢迎呢~杂货商要5个左右。" },
		Summary = "收集不死心脏5-向杂货商报告"
	},
	[12233] = {
		Title = "急救组的材料",
		Description = { "现在需要很多急救专用绷带的材料腐烂绷带，好像没有制作新绷带的材料。委托人是站在那边的杂货商，找来3捆左右就好！" },
		Summary = "收集腐烂绷带1-向杂货商报告"
	},
	[12234] = {
		Title = "勇猛的象征",
		Description = { "勇猛战士的标志给予冒险家的旅程很大的力量，所以兽人战士之证才能买得这么好吧！杂货商想要制作勇猛的象征的材料兽人战士之证3个。" },
		Summary = "收集兽人战士之证3-向杂货商报告"
	},
	[12235] = {
		Title = "对精气很好的……",
		Description = { "将骨头粉末参水喝下对精气很好的消息在冒险家之间传得沸沸扬扬的，杂货商要求制作强身剂所需的死人遗骨3个！" },
		Summary = "收集死人遗骨3-向杂货商报告"
	},
	[12236] = {
		Title = "符咒的最新流行",
		Description = { "虽然有许多人会将符咒披在身上，但通常都是密封在一个精美的礼盒中随身携带。亡者遗物对于制作包装很有用处，因此生活用品商想要2个。" },
		Summary = "收集亡者遗物2-向生活用品商报告"
	},
	[12237] = {
		Title = "贵重物品小心轻放",
		Description = { "冒险家对与自己生命有直接相关的符咒相当在乎，他们希望符咒可以完善无缺，因此生活用品商似乎是想利用坚硬外壳来制作相关产品，请带来3个左右。" },
		Summary = "收集坚硬外壳3-向生活用品商报告"
	},
	[12238] = {
		Title = "护膝带的材料",
		Description = { "来往于雾林迷宫的旅行者们经常会使用护膝带，因此生活用品商想要制作护膝带的材料鳞片皮肤3个。" },
		Summary = "收集鳞片皮肤3-向生活用品商报告"
	},
	[12239] = {
		Title = "以毒攻毒……",
		Description = { "接受到一个关于防毒虫剂的委托，生活用品商欲对毒成分进行研究，因此需要毒牙2个。" },
		Summary = "收集毒牙2-向生活用品商报告"
	},
	[12240] = {
		Title = "不能滑倒",
		Description = { "可以防脚滑的材料似乎都用光了，因此生活用品商需要粘稠液体5个。" },
		Summary = "收集粘稠液体5-向生活用品商报告"
	},
	[12241] = {
		Title = "萌萌的委托",
		Description = { "已经从萌萌那接受委托。" },
		Summary = "24小时后才可再次接受委托。",
		CoolTimeQuest = 1
	},
	[12242] = {
		Title = "康棱的委托",
		Description = { "已经从康棱那接受委托。" },
		Summary = "24小时后才可再次接受委托。",
		CoolTimeQuest = 1
	},
	[12243] = {
		Title = "失踪者达查勒的相关情报",
		Description = { "达查勒。年龄:32岁。来自米德加尔特。到雾林迷宫采集植物后便下落不明，至今已3个月。存活可能性:微薄。" },
		Summary = "雾林迷宫13x,10x附近"
	},
	[12244] = {
		Title = "失踪者纳伊查的相关情报",
		Description = { "年龄:19岁。从不明的远方乘船而来的冒险家，不顾穆拉村民的劝阻，执意以紧身裤装扮至迷宫内部探险，至今已失踪2个月。就算存活也会是救援队的负担。" },
		Summary = "雾林迷宫10x,24x附近"
	},
	[12245] = {
		Title = "失踪者梅斯的相关情报",
		Description = { "年龄:不详。有点精神病的症状。说要净化雾林迷宫后便只身前往。虽然强调自己是某大陆的贵族，但没有人相信。失踪至今已12年。存活可能性:0。" },
		Summary = "雾林迷宫14x,24x附近"
	},
	[12246] = {
		Title = "失踪者诺瓦讷伊的相关情报",
		Description = { "年龄:51岁。企图遍行全世界偷取名剑。晚年经营赌场时，因牵涉命案故藏身于雾林迷宫中。存活可能性:微薄。" },
		Summary = "雾林迷宫19x,27x附近"
	},
	[12247] = {
		Title = "失踪者绒绒的相关情报",
		Description = { "22岁。飞空艇飞行员实习生。休假期间来穆拉村喝酒时突然失踪。根据传言指出，他是因为杀人所以才逃到迷宫中。失踪至今已4个月。存活可能性:微薄。" },
		Summary = "雾林迷宫30x,32x附近"
	},
	[12248] = {
		Title = "失踪者梦特的相关情报",
		Description = { "年龄:不详。长发且身穿黑色衣服的女性。说要寻找长生不老后便前往迷宫探险。失踪至今已３个月。存活可能性：微薄。" },
		Summary = "雾林迷宫33x,28x附近"
	},
	[12249] = {
		Title = "失踪者马伊比德的相关情报",
		Description = { "年龄：50多。穆拉村的现任村长，涉嫌贪污因此逃亡至迷宫中。目前生死不明。" },
		Summary = "雾林迷宫33x,17x附近"
	},
	[12250] = {
		Title = "失踪者昆蒙的相关情报",
		Description = { "年龄：29岁。背景不详的年轻人。先是假装想在穆拉村定居，因此努力工作，后来因涉嫌诈取1200个穆拉币，便趁半夜逃亡至迷宫中。目前生死不明。" },
		Summary = "雾林迷宫28x,8x附近"
	},
	[12251] = {
		Title = "失踪者查伊豪金的相关情报",
		Description = { "34岁。对穆拉村的女性们频送秋波，后来被人发现其实是个花花公子。用餐途中为闪避想抓自己的居民们，因而逃至迷宫中。目前生死不明。" },
		Summary = "雾林迷宫17x,5x附近"
	},
	[12252] = {
		Title = "失踪者德尔的相关情报",
		Description = { "年龄不详。来到穆拉村已经超过6年，整天游手好闲，不事生产。因为受到居民们的白眼，便将村民们共同管理的存钱筒拿走并消失。存活可能性:微薄。" },
		Summary = "雾林迷宫11x,4x附近"
	},
	[12253] = {
		Title = "搜查失踪者结束",
		Description = { "搜查失踪者是非常累人的，因此在经过24小时前无法再额外进行搜查。" },
		Summary = "经过24小时前无法额外搜查。",
		CoolTimeQuest = 1
	},
