	[12292] = {
		Title = "不明人士",
		Description = { "建设家园树和让彩虹桥大地重生的主角不是正史所记载的长老会，而是两名默默无闻的传道师，有关艾德朗和罗贝勒两名传道师的情报去问克利佛！" },
