	[13000] = {
		Title = "收集RWC2011卡片",
		Description = { "收集蓝色卡片后来完成RWC2011吧！" },
		Summary = ""
	},
	[13001] = {
		Title = "收集RWC2011卡片-等候",
		Description = { "今日的广宣已完成！一天后再去找广宣人员吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13002] = {
		Title = "冒险家的条件 – 收集布里刊",
		Description = { "仓库里的布里刊应该差不多满了吧？不够的话赶快再继续收集呀！在克雷斯特汉姆古城和龟岛应该满容亦可以找到。" },
		Summary = "收集布里刊50个"
	},
	[13003] = {
		Title = "似笑非笑",
		Description = {
			"来自梦罗克一位商人的委托，他表示在克雷斯特汉姆古城有个名叫卡拉特小丑的怪物，在这一年以来因为怪物饭卖的冰淇淋害他的生意做不下去。乐园团当然不认为那是主要原因……但委托就是委托！"
		},
		Summary = "消灭卡拉特小丑 30只"
	},
	[13004] = {
		Title = "消灭卡拉特小丑 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13005] = {
		Title = "真的假不了！",
		Description = {
			"你知道在异国的果实中，有种叫豆子的果实吧？据说卷甲虫卷成圆形后的模样和那个叫豆子的果实很像呢！而从豆子里开出的花就是异国的国花，要是将两者搞混的话可不妙呢！"
		},
		Summary = "消灭卷甲虫 22只"
	},
	[13006] = {
		Title = "消灭卷甲虫 – 等候",
		Description = { "委托固然重要，但物种也很重要，执行委托时请小心别让卷甲虫绝种！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13007] = {
		Title = "圣地巡礼 - 1",
		Description = { "据说现在有种旅行行程是，通过地下水道可参观至修道院的最下层，为确保巡礼的安全，委托请求协助消灭地下水道的虎蜥人。" },
		Summary = "消灭虎蜥人 30只"
	},
	[13008] = {
		Title = "消灭虎蜥人 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13009] = {
		Title = "圣地巡礼 - 2",
		Description = { "为确保巡礼的安全，委托请求协助消灭地下水道和地下洞窟道的史汀。" },
		Summary = "消灭史汀 30只"
	},
	[13010] = {
		Title = "消灭史汀 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13011] = {
		Title = "圣地巡礼 - 3",
		Description = { "为确保巡礼的安全，委托请求协助消灭地下洞窟道2楼的狂暴米诺斯。" },
		Summary = "消灭狂暴米诺斯 30只"
	},
	[13012] = {
		Title = "消灭狂暴米诺斯 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13013] = {
		Title = "对冒险家们的体贴",
		Description = { "捕虫堇妖应该是进出异界的冒险家最先会遇到的怪物之一，远征队基地表示希望可减少周围怪物的数量，毕竟怪物多的话危险也多，这个委托还满普通的呢！" },
		Summary = "消灭捕虫堇妖 30只"
	},
	[13014] = {
		Title = "消灭捕虫堇妖 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13015] = {
		Title = "创伤",
		Description = { "这个算是私人的委托，因为小时候被蜜蜂螫过的创伤，导致这次在异界的旅行……咳咳……是最近来异界旅行的来越来越多，所以这个委托是必须的！" },
		Summary = "消灭鲁修拉黄蜂 30只"
	},
	[13016] = {
		Title = "消灭鲁修拉黄蜂 – 等候",
		Description = { "这种愚蠢的委托真是委屈你了，先休息一下再过来吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13017] = {
		Title = "与狼共舞",
		Description = { "听说拉赫北边的冰洞穴成为新兴的观光景点呢！请消灭冰洞穴周围的沙漠之狼。" },
		Summary = "消灭沙漠之狼 30只"
	},
	[13018] = {
		Title = "消灭沙漠之狼 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13019] = {
		Title = "吵人的家伙",
		Description = { "那些雪兽粗旷的呼吸声似乎影响到冒险家的精神，请消灭那些吵人的家伙们。" },
		Summary = "消灭雪兽 30只"
	},
	[13020] = {
		Title = "消灭雪兽 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13021] = {
		Title = "巨人？巨人！",
		Description = {
			"你应该有去过拉赫地区的冰洞穴吧？在3楼有个叫作冰巨人的怪物，学者们最近很热衷于研究他到底是不是巨人，做研究固然很好，但这样下去会有危险，所以要请你减少他们的数量！"
		},
		Summary = "消灭冰巨人 30只"
	},
	[13022] = {
		Title = "消灭冰巨人 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13023] = {
		Title = "流逝回忆中的你",
		Description = { "先前曾经和爱人同游熔岩洞穴的幸福回忆，在分手后想旧地重游一下，没想到只剩一堆可怕的怪物，真是令人伤心的故事。少女的回忆由你来守护！" },
		Summary = "消灭七彩梦魇 30只"
	},
	[13024] = {
		Title = "消灭七彩梦魇 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13025] = {
		Title = "最后一支舞",
		Description = {
			"从委托的内容看来，似乎是在和爱人共舞时受到七彩飞龙的干扰，结果几天后收到分手通知……因此对七彩飞龙怀恨在心……的样子。我们绝不允许伤害爱情和少女回忆的事情发生！请消灭 七彩飞龙！"
		},
		Summary = "消灭七彩飞龙 30只"
	},
	[13026] = {
		Title = "消灭七彩飞龙 – 等候",
		Description = { "休息是为了走更长远的路！为下一次的委托存储器力吧！" },
		Summary = "",
		CoolTimeQuest = 1
	},
	[13027] = {
		Title = "Hyo-yeo's Crescent Moon's Request",
		Description = {
			"Let's bring the persimmon and mugwort cake for the grandmother who will be alone. But where did you get this? Let's go to the mill first."
		},
		Summary = "Let's go to the mill"
	},
	[13028] = {
		Title = "Clean and confident",
		Description = {
			"Let's get stellar powder and honey for skin care for people who don't know."
		},
		Summary = "Collect 5 honey powders and 2 honeys"
	},
	[13029] = {
		Title = "Clean and confident with confidence-waiting",
		Description = {
			"Skin care is important! Let's help her again over time."
		},
		Summary = "Reset at 04:00",
		CoolTimeQuest = 1
	},
	[13030] = {
		Title = "Request of the Mill",
		Description = {
			"Let's run the errand of the owner of the busy millet. Bring the bread to the grandfather and return."
		},
		Summary = "Let's return the rice cake to the growler."
	},
	[13031] = {
		Title = "Find Vandalja,",
		Description = {
			"Let's find a man who has become a human being and send him a letter. Do you know the location of the weeds in the north of Payon?"
		},
		Summary = "You send a letter to Mr. Vandalga and come back."
	},
	[13032] = {
		Title = "Perseverance of Weedling",
		Description = {
			"Let's collect 10 green and white herbs for weed planting."
		},
		Summary = "Collect 10 green herbs and 10 white herbs"
	},
	[13033] = {
		Title = "Patience of Weedling-Waiting",
		Description = {
			"Let's look for weeds over time to show the stickiness of weeds."
		},
		Summary = "Reset at 04:00",
		CoolTimeQuest = 1
	},
	[13034] = {
		Title = "With love for the persimmon and mugwort cake",
		Description = {
			"Once I got the persimmon and mugwort rice cake, let's bring it to my grandmother full moon."
		},
		Summary = "Delivery to the grandmother of the archer village!"
	},
	[13035] = {
		Title = "For my beloved grandmother",
		Description = {
			"For a bored grandmother, I want to gather a story for you. Let's meet Crescent Moon and Mr. Bandalaga."
		},
		Summary = "Let's tell the story of the growl and Mr. Vandalaga to the grandmother."
	},
	[13036] = {
		Title = "For my beloved grandmother-waiting",
		Description = {
			"It seems that my grandmother enjoyed meeting people rather than telling the story. If you have time, let me hear you again."
		},
		Summary = "Reset at 04:00",
		CoolTimeQuest = 1
	},
	[13037] = {
		Title = "The story of the growl",
		Description = {
			"I heard the story of growl. It is subtly strange, but grandma might like it."
		},
		Summary = ""
	},
	[13038] = {
		Title = "The story of Mr. Vandal",
		Description = {
			"I heard the story of Mr. Vandalaga. It's unknown whether Grandma would like it."
		},
		Summary = ""
	},
	[13039] = {
		Title = "I got mugwort rice cake",
		Description = {
			"I got mugwort rice cake! Now I need to get the persimmon ... I think the growl asked me to come."
		},
		Summary = "Let's meet the growl."
	},
	[13040] = {
		Title = "哈阿哈阿",
		Description = { "秘密团队中的有个秘密团体叫[女神与足球]的组织委托说银月魔女怪对冒险家造成威胁而希望去解决它。 会有邀请更难的事情之前,一定要接受此任务。" },
		Summary = "处理银月魔女 30条"
	},
	[13041] = {
		Title = "处理银月魔女 – 等待",
		Description = { "修习也是遂行！接下一个任务之前,去充分的休息。" },
		Summary = "",
		CoolTimeQuest = 1
