	},
	[14118] = {
		Title = "吴哈里的担忧",
		Description = { "吴哈里担心关在监狱里的哥哥，把吴哈里的问候信交给监狱里的吴虎路吧！" },
		Summary = "把信交给吴虎路。"
	},
	[14119] = {
		Title = "耐心考验",
		Description = { "想与监狱里的囚犯交谈却无回应，似乎是在考验耐心。" },
		Summary = "与囚犯对话。"
	},
	[14120] = {
		Title = "耐心考验2",
		Description = { "虽然再次想与他攀谈却仍无响应，再试一次吧！" },
		Summary = "与囚犯对话。"
	},
	[14121] = {
		Title = "耐心考验3",
		Description = { "让他开口似乎很难，有没有方法呢？" },
		Summary = "与囚犯对话。"
	},
	[14122] = {
		Title = "两人的时刻",
		Description = { "把弟弟的信交给了吴虎路，他要求给点时间看信，不要妨碍他好了，" },
		Summary = "看信的时间。"
	},
	[14123] = {
		Title = "吴虎路的请托",
		Description = { "吴虎路看完弟弟秀后托你向弟弟问候，再去找吴哈里表达哥哥的问候吧！" },
		Summary = "向吴哈里转达哥哥的问候。"
	},
	[14124] = {
		Title = "首次委托",
		Description = { "杰宜德所养的动物一夜间被人偷走了，去调查怎么一回事!" },
		Summary = "去杰宜德的家"
	},
	[14125] = {
		Title = "查问周围",
		Description = { "想办法让吴虎路找回原貌的吴哈里，只是毫无头绪，先去询问当时在场的居民吧？ 那就先去村落找找吧！" },
		Summary = "询问村民。"
	},
	[14126] = {
		Title = "寻找高娣",
		Description = { "马西奥说自己不清楚，建议去找高娣应该能问出所以然来……" },
		Summary = "寻找高娣。"
	},
	[14127] = {
		Title = "寻找高娣的先生",
		Description = { "高娣说曾看到吴虎路开心的挥舞着某张纸，只是那张纸行踪不明，她先生可能知道叫你去找他。" },
		Summary = "寻找高娣的先生。"
	},
	[14128] = {
		Title = "获得研究书",
		Description = { "吴虎路的挚友史贝利果然不同，在吴虎路关进监狱前转达的信件内有研究书，拿给吴哈里吧！" },
		Summary = "转达研究书。"
	},
	[14131] = {
		Title = "分析时间",
		Description = { "收下研究书的吴哈里，只是太复杂分析需要一些时间，为了让他专心分析稍后再与他对话吧！" },
		Summary = "研究书分析时间。"
	},
	[14132] = {
		Title = "调查动物窝",
		Description = { "先去调查动物的窝。" },
		Summary = "调查动物窝"
	},
	[14133] = {
		Title = "另一个请托",
		Description = { "分析完研究书的吴哈里，只是看完研究书后仍找不出让哥哥回复原貌的方法，现在该去找当初向吴虎路委托研究的守护精灵询问吧！" },
		Summary = "寻找线索。"
	},
	[14134] = {
		Title = "包打听高娣",
		Description = { "再去找曾给寻找研究书线索的史贝利，只是他对守护精灵高层一无所知，他建议去找自己的包打听太太。" },
		Summary = "去找高娣。"
	},
	[14135] = {
		Title = "寻找彭拜",
		Description = { "虽向包打听高娣询问关于守护精灵高层的行踪，却无进展。但有说彭拜在原野上目击像鬼魂般消失的守护精灵，向彭拜问个清楚吧！" },
		Summary = "询问彭拜。"
	},
	[14136] = {
		Title = "原野上的悲剧",
		Description = { "彭拜不敢到原野去，曾目击某个守护精灵高层被杀后变成大型尸体，有必要原野调查一下。" },
		Summary = "调查原野。"
	},
	[14137] = {
		Title = "诚实的提议",
		Description = { "某个守护精灵少女提出诚实的建议，送给吴虎路研究书的守护精灵和少女所找的父亲可能是同一人，大家一起找吧！" },
		Summary = "调查原野。"
	},
	[14138] = {
		Title = "大型尸体",
		Description = { "发现了有一段时间的大型尸体，必须告知少女这不幸的消息。" },
		Summary = "通知稚娜妮。"
	},
	[14139] = {
		Title = "去找吴虎路",
		Description = { "少女已确认那大体是自己的父亲，知情的守护精灵已亡故，只能空手向吴哈里回报了，这之前向通知吴虎路守护精灵的死讯吧！" },
		Summary = "去找吴虎路。"
	},
	[14140] = {
