	[14549] = {
		Title = "无消息并非好消息",
		Description = { "去确认龙的状态的家伙还没回来。肯定是出事了，能一起去看看吗？" },
		Summary = "探索洞穴"
	},
	[14550] = {
		Title = "龙怎么样啊",
		Description = { "因为见到又大又恐怖的敌人还没见到塔鲁土皮。快去确认看看怎么样了可以吗？" },
		Summary = "确认龙的状态"
	},
	[14551] = {
		Title = "巴西利斯克首领",
		Description = { "去见见巴西利斯克们的首领螭龙拜托他们不要再惹事了。那边上面听说有可以对话的装置。" },
		Summary = "与螭龙对话"
	},
	[14552] = {
		Title = "螭龙的口信",
		Description = { "那小东西还给我们如意珠之前我们巴西利斯克会尽到我们的义务的。" },
		Summary = "告诉塔鲁土皮"
	},
	[14553] = {
		Title = "击退巴西利斯克",
		Description = { "那我找到如意珠前你帮我处理他们吧。一般除掉20只左右就不会再过来了。" },
		Summary = "处理巴西利斯克"
	},
	[14554] = {
		Title = "现在可以出海了",
		Description = { "处理巴西利斯克让塔鲁土皮安静了。去给大副斯泰罗报告吧。" },
		Summary = "给大副报告"
	},
	[14555] = {
		Title = "新的味觉世界",
		Description = { "想用新大陆的食材进行一次研究。可以帮我收集来玛丝黛拉果实吗？4个左右。还有那些传闻中救了蝴蝶号的船员们的猫饼干也收集几个就好了。这个就需要一个哦。" },
		Summary = "玛丝黛拉果实和猫饼干"
	},
	[14556] = {
		Title = "我也有害怕的东西",
		Description = { "因为每晚出现的那些而头疼。听说从新的地方出现的贵人会帮我解决这些问题。到神灵喵处听听我的问题的解决方法吧。神灵喵就住在村落刚进来的入口一角处。" },
		Summary = "去找神灵喵"
	},
	[14557] = {
		Title = "事实总是很残酷",
		Description = { "去给水手长告知我说的事情吧。" },
		Summary = "去找水手长"
	},
	[14558] = {
		Title = "脏东西们",
		Description = { "绝对不想接触巴西利斯克。所以你帮我去收集20个罗勒和5个蛤蜊吧。当然是有报酬的。" },
		Summary = "罗勒和蛤蜊"
	},
	[14559] = {
		Title = "护身符效果维持时间",
		Description = { "护身符效果到04点就会消失。" },
		Summary = "04点初始化",
		CoolTimeQuest = 1
	},
	[14560] = {
		Title = "新的材料",
		Description = { "最近与新大陆的人们的接触变多了，对那边的幸运符也有所了解。今天的幸运符是5个蛤蜊和1个圣水。找来后直接去找水手长吧。" },
		Summary = "蛤蜊和圣水"
	},
	[14561] = {
		Title = "脏脏的东西",
		Description = { "蛤蜊才是脏中最脏。蛤蜊20个的话今天一天应该可以消停了。收集好后去找水手长吧。" },
		Summary = "蛤蜊"
	},
	[14562] = {
		Title = "基础的才是最好的",
		Description = { "效果好的一直都会成为基础。罗勒20个和蛤蜊5个。收集过来后就去找水手长吧。" },
		Summary = "罗勒和蛤蜊"
	},
	[14563] = {
		Title = "悠闲的时间",
		Description = { "还没有完成今天的工作。工作结束才能对食材进行研究啊。过了凌晨后再来吧。" },
		Summary = "04点初始化",
		CoolTimeQuest = 1
	},
	[14564] = {
		Title = "我也喜欢包子",
		Description = { "听说新大陆有叫做包子的东西。罗札纳也有类似的食品，我想比比看，帮我收集来20个吧。" },
		Summary = "包子 20个"
	},
	[14565] = {
		Title = "应急粮食",
		Description = { "没有粮食的时候纳斯在蝴蝶号救起船员们的那储备粮食是什么啊，可以帮我弄来5个吗？" },
		Summary = "猫饼干，绵绵岛罐头"
	},
	[14566] = {
		Title = "天才的想法",
		Description = { "不融化的冰块！！如果有这种东西的话保管食材可是简单多了！帮我弄来20个吧！" },
		Summary = "冰块一角"
	},
	[14567] = {
		Title = "卡鲁哇牛奶危险了！",
		Description = { "说好提供卡鲁哇的雷格拉斯忽然联系不上了。过了今天可就无法喝到卡鲁哇牛奶了，在那之前快去见见雷格拉斯吧。他就在南边一直走就能见到。" },
		Summary = "去找雷格拉斯"
	},
	[14568] = {
		Title = "说服的时间",
		Description = { "这样的话我们就要饿死了！快帮我说服那两个家伙不要再吃卡鲁哇了！" },
		Summary = "达达和高帕拉"
	},
	[14569] = {
		Title = "婴儿保姆",
		Description = { "找找需要照顾的孩子吧。" },
		Summary = "照看宝宝"
	},
	[14570] = {
		Title = "处理？鱼",
		Description = { "既然想做关于？鱼的事情，那就去？鱼工作室吧。" },
		Summary = "？鱼工作室"
	},
	[14571] = {
		Title = "？鱼船籍渔船",
		Description = { "既然想乘坐船的话？鱼船籍渔船的事情的话应该可以适应吧。去找？鱼渔船去吧。" },
		Summary = "？鱼渔船"
	},
	[14572] = {
