		Description = { "埃里森给了可以和双胞胎一起吃的美味的饼干，带着饼干去哄一哄双胞胎，并好好听他们说的话吧。" },
		Summary = "回去找雷贝德夫双胞胎"
	},
	[16034] = {
		Title = "甜甜的饼干每天一次",
		Description = { "和元老们一起的茶点时间每天只有一次，凌晨过后再去找一下吧。" },
		Summary = "04点重置",
		CoolTimeQuest = 1
	},
	[16035] = {
		Title = "配送：爆发物质左轮手枪",
		Description = { "动不动就会坏掉的左轮手枪，快送去艾音布罗克的铁匠那里吧。" },
		Summary = "在艾音布罗克铁匠工会咨询"
	},
	[16036] = {
		Title = "租借熟练者的眼光",
		Description = { "把铁匠工会听到的结果带去告诉瑞切尔工匠" },
		Summary = "访问瑞切尔工匠"
	},
	[16037] = {
		Title = "配送材料1日1次",
		Description = { "送来的材料已经充足了，等过了凌晨再来看看缺不缺什么吧。" },
		Summary = "04点重置",
		CoolTimeQuest = 1
	},
	[16038] = {
		Title = "配送2个神之金属",
		Description = { "准备瑞切尔工匠委托的^0000CD神之金属^0000002个吧。" },
		Summary = "配送2个神之金属"
	},
	[16039] = {
		Title = "配送2个铝",
		Description = { "准备瑞切尔工匠委托的^0000CD铝^0000002个吧。" },
		Summary = "配送2个铝"
	},
	[16040] = {
		Title = "配送5个铁",
		Description = { "准备瑞切尔工匠委托的^0000CD铁^0000005个吧。" },
		Summary = "配送5个铁"
	},
	[16041] = {
		Title = "调查：散步喵捕获作战",
		Description = { "反叛者基地的散步喵慈慈过了饭点还不出现。^0000cd艾音贝赫的空长椅^000000处好好找找用?鱼饼干引诱回来吧。" },
		Summary = "从艾音贝赫带来慈慈"
	},
	[16042] = {
		Title = "慈慈很是悠闲",
		Description = { "慈慈正在非常悠闲地玩耍，暂时可以放心了，等凌晨再来吧。" },
		Summary = "04点重置",
		CoolTimeQuest = 1
	},
	[16043] = {
		Title = "调查：某人的欲望捕获作战",
		Description = { "米洛 玮玮好像很想抚摸慈慈，好像不会伤害它，就像以前一样在^0000CD艾音贝赫的空长椅附近^000000用?鱼饼干引诱猫咪吧。" },
		Summary = "从艾音贝赫带来慈慈"
	},
	[16044] = {
		Title = "慈慈在慈慈的位置上",
		Description = { "找到了慈慈！把正吃着？鱼饼干忘我的慈慈抱去给米洛玮玮吧。" },
		Summary = "回去找玮玮"
	},
	[16045] = {
		Title = "老将的小小追悼仪式",
		Description = { "埃里森委托冒险家到艾音布罗克望台南边牌匾下面，把从小孩处买来的几朵鲜花放置祭奠吧。到艾音布罗克帮他吧。" },
		Summary = "艾音布罗克牌匾下献花"
	},
	[16046] = {
		Title = "DIY 收集花束材料",
		Description = { "艾音布罗克卖花小孩委托收集花束的材料。收集^0000CD光滑的纸^0000003张吧。" },
		Summary = "收集3张光滑的纸"
	},
	[16047] = {
		Title = "寂静的追悼仪式",
		Description = { "从卖花的小孩处获得了花束。放到^0000cd树下小牌匾^000000前吧。" },
		Summary = "把花束献祭在树下"
	},
	[16048] = {
		Title = "古老的故事的印记",
		Description = { "听了非常长久的故事，完成委托，回去告诉埃里森吧。" },
		Summary = "回去找埃里森"
	},
	[16049] = {
		Title = "寂静的凌晨",
		Description = { "亡者也需要休息，等凌晨过后再来吧。" },
		Summary = "04点重置",
		CoolTimeQuest = 1
	},
	[16050] = {
		Title = "追悼的时间",
		Description = { "埃里森再次委托冒险家购买花束到艾音布罗克望台南边小牌匾下献祭花束。为了完成委托快去艾音布罗克吧。" },
		Summary = "艾音布罗克牌匾下献祭鲜花"
	},
	[16051] = {
		Title = "DIY 收集花束材料",
		Description = { "艾音布罗克的卖花的小孩说制作花束的材料用完了，收集^0000CD光滑的纸^0000003张带过来吧。" },
		Summary = "收集3张光滑的纸"
	},
	[16052] = {
		Title = "寂静的追悼仪式",
		Description = { "今天也说好在^0000cd树下的小牌匾^000000下放置花束。希望小小年纪夭折的小女孩能够安息。" },
		Summary = "把花束献祭在树下"
	},
	[16053] = {
		Title = "古老并持续的故事",
		Description = { "完成了委托，回去和埃里森报告吧。" },
		Summary = "回去找埃里森"
	},
	[16054] = {
		Title = "不一样的广告战略",
		Description = { "梅森 班德发挥自己的文采编写的武器店宣传单，快给艾音贝赫人们发放吧。" },
		Summary = "在艾音贝赫发放宣传单"
	},
	[16055] = {
		Title = "广告：想要干净的村落吗？",
		Description = { "把非常华丽的书写的广告纸发给^0000CD疲惫的大叔^000000。" },
		Summary = "发给疲惫的大叔"
	},
	[16056] = {
		Title = "广告：这样的话全都飞掉吧！",
		Description = { "把印在非常贵的纸上的广告纸硬塞给^0000CD累坏的老先生^000000。" },
		Summary = "发给累坏的老先生"
	},
	[16057] = {
		Title = "广告：为陈旧的仇恨报仇也很好！",
		Description = { "把印成彩色的广告纸给叠成扇子给了^0000CD爱困的老奶奶^000000。" },
		Summary = "发给爱困的老奶奶"
	},
	[16058] = {
		Title = "广告效果还要慢慢看",
		Description = { "梅森在等着客人疯狂涌来，等凌晨过后再来确认效果吧。" },
		Summary = "04点重置",
		CoolTimeQuest = 1
	},
	[16059] = {
		Title = "有点不一样的广告战略",
		Description = { "梅森看来还没放弃，还想发放广告单，总感觉省下这笔钱会更好……" },
		Summary = "在艾音贝赫发放宣传单"
	},
	[16060] = {
		Title = "战争狂的语言就是战斗",
		Description = { "埃琳娜用非常感兴趣的眼神看着你，去和埃琳娜对话后进入待机室吧。" },
		Summary = "击败埃琳娜"
	},
