	[21001] = {
		Title = "逃离失事轮",
		IconName = "ico_gq.bmp",
		Description = { "必须从旅行中遇到大海浪后搁浅在无人岛的船舶中逃出去，并告诉外面的人船内还有伤者。" },
		Summary = "与船长对话"
	},
	[21002] = {
		Title = "最初的战斗",
		Description = { "波利把修船的木材给偷走了，必须击杀波利后收集木材2个给船员，去附近猎捕波利后回收木材吧!" },
		Summary = "把木材2个交给船员"
	},
	[21003] = {
		Title = "晕船特效药",
		Description = { "必须带来可舒缓雷诺晕船的药水，去^4d4dff克里图拉学院医务室^000000找^4d4dff治疗师询问有关药草^000000的事情吧!" },
		Summary = "向治疗师询问药草学"
	},
	[21004] = {
		Title = "基础药草学",
		Description = { "治疗师说要采药水材料之一的红色药草，去^4d4dff克里图拉正门外^000000找^4d4dff红色草^000000吧!" },
		Summary = "去正门外找红色草"
	},
	[21005] = {
		Title = "记忆点!",
		Description = { "收到了好东西。" },
		Summary = ""
	},
	[21006] = {
		Title = "告诉雷诺好消息",
		Description = { "把治疗师给的药水交给雷诺。" },
		Summary = "与雷诺对话"
	},
	[21007] = {
		Title = "初次见面的朋友",
		Description = { "认识了不错的朋友。" },
		Summary = ""
	},
	[21008] = {
		Title = "最初的战斗",
		IconName = "ico_gq.bmp",
		Description = { "波利把修船的木材给偷走了，必须击杀波利后收集木材2个给船员，去附近猎捕波利后回收木材吧!" },
		Summary = "把木材2个交给船员"
	},
	[21009] = {
		Title = "斯瀑拉齐的呼叫",
		Description = {
			"公会呼叫说伊甸园有了委托，去找依斯鲁得岛北边克里图拉学院的<NAVI>[斯瀑拉齐]<INFO>iz_ac01,102,44,000,0</INFO></NAVI>。"
		},
		Summary = "与斯瀑拉齐对话"
	},
	[21011] = {
		Title = "吊桶里的酒",
		Description = { "必须协助斐扬的爷爷把储藏在井里的私酿酒拉上来，快到旁边的井水把装在吊桶里的酒拉上来吧!" },
		Summary = "在井水边把吊桶拉上来"
	},
	[21012] = {
		Title = "孙子的行踪",
		Description = { "必须找到从斐扬北边弓箭手村偷偷溜走的爷爷的孙子，先去询问弓箭手村洞穴前的警备兵吧!" },
		Summary = "与洞穴警备兵对话"
	},
	[21013] = {
		Title = "有得必有失",
		Description = { "去找孙子的雷诺还留在洞穴内，快去斐扬洞穴里找雷诺吧!" },
		Summary = "与洞穴内的雷诺对话"
	},
	[21014] = {
		Title = "又臭又滑的鬼怪",
		Description = { "为了超怕腐尸的雷诺，帮忙清除附近的腐尸5只吧吧!" },
		Summary = "为了雷诺击杀腐尸"
	},
	[21015] = {
		Title = "不死战争",
		IconName = "ico_dq.bmp",
		Description = { "斐扬警备兵因为日渐增多的腐尸和邪骸战士而头痛不已，需要协助击杀腐尸10只和邪骸战士20只，而邪骸战士位于洞穴的更深处。" },
		Summary = "击杀斐扬洞穴里的不死型怪"
	},
	[21016] = {
		Title = "不死战争-等候",
		IconName = "ico_dq.bmp",
		Description = { "此为每日任务，冷却时间过后可再承接执行，可透过伊甸园布告栏或斐扬的弓箭手村士兵来承接任务。" },
		Summary = "凌晨四点重置",
		CoolTimeQuest = 1
	},
	[21017] = {
		Title = "净化灵魂仪式",
		IconName = "ico_dq.bmp",
		Description = { "为了超度以前因山崩被灭村的冤魂们，需要一些'返魂符'，去打僵尸和妖道后收集返魂符吧!僵尸和妖道出现在斐扬洞穴3楼。" },
		Summary = "返魂符15张"
	},
	[21018] = {
